// Visual-variety pools. When the resolved emoji has multiple variants in the
// workspace (e.g. :truck:/:truck2:/:truck3:), pick one deterministically off
// the opp Id so the same opp always renders the same icon, but the channel
// at-a-glance doesn't look like every win is the same picture.
// Variant pools rotate per-opp via hashIndex(oppId) so the same opp always
// renders the same emoji while the channel sees variety. Pools are partitioned
// across industries — no emoji is shared between distinct industries.
const VARIANT_GROUPS = {
  ':truck:':              [':truck:', ':truck2:', ':truck3:'],
  ':construction_worker:': [':construction_worker:', ':hard-hat:'],
  // Equipment Rental (POR's core market). Owns the construction-equipment
  // family; Heavy Equipment renders as :heavy-machine: alone for separation.
  ':equipment:':          [':equipment:', ':bulldozer:', ':bulldozer2:', ':excavator2:', ':backhoe:'],
};

function resolveVariant(emoji, oppId, exclude = null) {
  const variants = VARIANT_GROUPS[emoji];
  if (!variants || variants.length <= 1) return emoji;
  const pool = exclude ? variants.filter(v => v !== exclude) : variants;
  if (pool.length === 0) return emoji; // can't avoid the dupe — fall back to base
  return pool[hashIndex(oppId || '', pool.length)];
}

// `exclude` lets the caller request a different variant than one already in
// use on the same opp — used to keep Industry and Sub-Industry from rendering
// the same emoji when both map to the same variant pool (e.g. Equipment Rental
// + General Tool & Equipment Rental both map to :equipment: → :bulldozer:).
function industryEmoji(industry, oppId = '', exclude = null) {
  if (!industry) return '';
  const trimmed = String(industry).trim();
  if (!trimmed) return '';
  if (INDUSTRY_EMOJI[trimmed]) return resolveVariant(INDUSTRY_EMOJI[trimmed], oppId, exclude);
  for (const [pattern, emoji] of KEYWORD_FALLBACK) {
    if (pattern.test(trimmed)) return resolveVariant(emoji, oppId, exclude);
  }
  return ':office:';
}

// Deterministic pseudo-random index from a string — used to pick stable
// per-Opp variants for cycle labels and coach lines.
function hashIndex(str, mod) {
  if (!str) return 0;
  let h = 0;
  for (let i = 0; i < str.length; i++) {
    h = ((h << 5) - h + str.charCodeAt(i)) | 0;
  }
  return Math.abs(h) % mod;
}

// Per-day burn rate — a fun "$X/day to close" stat for the context footer.
function dailyBurn(usdAcv, days) {
  if (usdAcv == null || days == null || days <= 0) return null;
  const perDay = Math.round(usdAcv / days);
  if (perDay <= 0) return null;
  return `$${perDay.toLocaleString()}/day to close`;
}

// Coach line — one snappy sportscaster sentence celebrating the win shape.
// Dynamic across interaction-intensity buckets, with deterministic variety
// per Opp ID via hashIndex so the same opp always renders the same line.
//
// This is a CELEBRATION, not a coaching session — every variant is a tip-of-
// the-cap observation. No "do better next time" / advice on a deal that's
// already closed-won.
function coachLine({ counts, acvUsd, oppId }) {
  const total = counts?.total || 0;
  const emails = counts?.emails || 0;

  let pool;
  if (total === 0) {
    // Special case: nothing to celebrate when there are zero touches in the
    // log, so the data-logging nudge is appropriate here (and only here).
    pool = [
      ':ghost: *Phantom close.* Zero recorded interactions — log the next one for the data team!',
      ':eyes: *No paper trail* on this one. Future-you will thank present-you for logging.',
    ];
  } else if (total <= 4) {
    pool = [
      `:dart: *${total}-interaction close.* Surgical efficiency.`,
      `:zap: *${total}-interaction sprint.* Quick and clean.`,
      `:rocket: *Lean ${total}-interaction run.* Speed wins.`,
    ];
  } else if (total <= 12) {
    pool = [
      `:checkered_flag: *${total}-interaction rhythm.* Right in the pocket.`,
      `:hammer: *${total} interactions built this.* Solid foundation.`,
      `:trophy: *${total}-interaction close.* Textbook execution.`,
    ];
  } else if (total <= 25) {
    pool = [
      `:fire: *${total}-interaction closure!* This is what high-functioning sales looks like.`,
      `:muscle: *${total} interactions across the funnel.* The data team smiles every time you log activity.`,
      `:leo-toast: *${total}-interaction grind paid off.* This is the playbook.`,
    ];
  } else if (total <= 50) {
    pool = [
      `:strong-rocket: *${total}-interaction master class.* Sequencing on lock.`,
      `:bow_and_arrow: *${total} interactions!* You ran a campaign, not a pitch. Bravo.`,
      `:winning: *${total}-interaction onslaught.* This is how big deals get caught.`,
    ];
  } else {
    pool = [
      `:money-in-the-bank: *${total}-interaction siege.* Whale-treatment. Beautiful.`,
      `:mvp: *${total}-interaction saga.* This is the case-study deal.`,
      `:open_book: *${total} interactions?!* Legendary sequencing — one for the playbook.`,
    ];
  }

  let line = pool[hashIndex(oppId || '', pool.length)];

  // Email-volume callout — celebratory only. Power-user move at high volume.
  if (emails >= 15) {
    line += `  ·  :email: *${emails} emails* — power-user move.`;
  }

  return line;
}

// SF gives `CreatedDate` as a full ISO timestamp ("2026-05-12T14:23:45Z") and
// `CloseDate` as a date-only string ("2026-05-12"). JS parses the date-only
// form as UTC midnight, so naive timestamp math against an afternoon-UTC
// CreatedDate yields a negative diff that rounds to -1d for same-day wins.
// Slice both to YYYY-MM-DD and compute the calendar-day delta instead.
function daysBetween(startIso, endIso) {
  if (!startIso || !endIso) return null;
  const start = utcMidnightOfDate(startIso);
  const end = utcMidnightOfDate(endIso);
  if (start == null || end == null) return null;
  return Math.round((end - start) / 86400000);
}

function utcMidnightOfDate(iso) {
  const m = String(iso).match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (!m) return null;
  return Date.UTC(parseInt(m[1], 10), parseInt(m[2], 10) - 1, parseInt(m[3], 10));
}

const ISO_DATE = /^\d{4}-\d{2}-\d{2}/;
function formatDateLong(iso) {
  if (!iso || !ISO_DATE.test(iso)) return '**';
  const d = new Date(iso);
  return d.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: '2-digit', timeZone: 'UTC' });
}

// Build a Slack mention. Prefer real <@USER_ID> if resolved, fallback to *Name*.
function slackMention(name, userId) {
  if (userId) return `<@${userId}>`;
  if (name) return `*${name}*`;
  return 'None';
}

// Pretty print "1 location, 2 users" or "3 locations, 18 users".
// Only consumed by tests/format.test.js — kept for backwards-compat.
function locationsAndUsers(opp) {
  const locs = opp.Number_of_Locations__c;
  const users = opp.NumUsers__c;
  if (locs == null && users == null) return null;
  const locStr = locs == null ? '' : `${locs} location${locs === 1 ? '' : 's'}`;
  const usersStr = users == null ? '' : `${users} user${users === 1 ? '' : 's'}`;
  return [locStr, usersStr].filter(Boolean).join(', ') || null;
}

// "Summit, Mississippi, United States" or "Pinkenba, Queensland, Australia"
function locationLine(opp) {
  const a = opp.Account || {};
  const parts = [a.BillingCity, a.BillingState, a.BillingCountry].filter(Boolean);
  return parts.length ? parts.join(', ') : null;
}
function opportunityUrl(oppId) {
  return `https://por.lightning.force.com/lightning/r/Opportunity/${oppId}/view`;
}
function accountUrl(accountId) {
  if (!accountId) return null;
  return `https://por.lightning.force.com/lightning/r/Account/${accountId}/view`;
}

// Google Maps deep link from billing address. Falls back to account-name search
// when no city, returns null only when there's literally nothing to search.
//   "Cardinal Hardware Summit Mississippi United States"
//   → https://www.google.com/maps/search/?api=1&query=Cardinal+Hardware+...
function mapUrl(opp) {
  const a = opp?.Account || {};
  const parts = [a.Name, a.BillingCity, a.BillingState, a.BillingCountry].filter(Boolean);
  if (parts.length === 0) return null;
  return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(parts.join(' '))}`;
}

// Account website normalizer — ensures protocol is present so the link is clickable.
function websiteUrl(website) {
  if (!website) return null;
  if (/^https?:\/\//i.test(website)) return website;
  return `https://${website}`;
}

// Google-search fallback for accounts missing a Website on SF — keeps the
// "Website" action button useful for every customer. Includes city + state
// alongside the name because common-name accounts (e.g. "Cardinal Hardware")
// otherwise return the wrong company; address disambiguates without hurting
// unique names. Returns null only if Account.Name is also missing.
function accountWebsiteOrSearchUrl(account) {
  const direct = websiteUrl(account?.Website);
  if (direct) return direct;
  const name = account?.Name?.trim();
  if (!name) return null;
  const parts = [name, account?.BillingCity, account?.BillingState].filter(Boolean);
  return `https://www.google.com/search?q=${encodeURIComponent(parts.join(' '))}`;
}


// === product-emoji.js ===
// Product → emoji mapping for the Deal Overview line.
// All custom emojis below are confirmed present in the POR Slack workspace
// (verified via emoji.list — 1036 custom emojis available).
//   :elitepng:        — Rental Elite logo (PNG)
//   :essentialsicon:  — Rental Essentials logo
//   :Record360:       — Record360 logo (animated GIF — case-sensitive emoji name)
//   :point-of-rental: — POR corporate logo (used as Syrinx fallback)
//
// NOTE: Inspect360 / InspectPro are NOT separate products — they're R360
// product-family entries that should always render as "Record360".
// NOTE: Texada is a COMPETITOR, not a POR product — intentionally excluded.

const PRODUCT_EMOJI = {
  'Rental Elite': ':elitepng:',
  'Rental Essentials': ':essentialsicon:',
  'Rental Expert': ':wayne:',
  'Syrinx': ':por:',
  'Record360': ':Record360:',
  'POROne': ':one:',
};

// Aliases for product-family values that should be normalized to a canonical
// product name before lookup. e.g. Inspect360 / InspectPro both belong to the
// Record360 family — the SF picklist has them as separate values but they're
// the same product to sales/RevOps.
const PRODUCT_LABEL_ALIASES = {
  'Inspect360': 'Record360',
  'InspectPro': 'Record360',
  'Inspect Pro': 'Record360',
};
function productEmoji(productName) {
  if (!productName) return ':star:';
  const canonical = PRODUCT_LABEL_ALIASES[productName] || productName;
  return PRODUCT_EMOJI[canonical] || ':star:';
}
function productLabel(opp) {
  const raw = opp.Product_Family__c || opp.ProductFamilyText__c || null;
  if (!raw) return null;
  return PRODUCT_LABEL_ALIASES[raw] || raw;
}

// Cloud vs On-Prem deployment. Detected from the opp's line items, not the
// product family — Rental Elite, Syrinx, and Rental Expert are all sold in
// BOTH cloud and on-prem flavors. Reps pick the variant by selecting the
// `(Cloud)` or `(On-Premise)` SKU at quote time, e.g.:
//   "Elite Basic User License (Cloud)"            → Cloud
//   "Syrinx 365 Basic User License (On-Premise)"  → On-Prem
// The line items also carry Product2.Deployment_Type__c on the SKUs that
// matter — used as a second signal.
//
// Products that are sold in only one mode (Rental Essentials = cloud SaaS,
// Record360 = cloud-only, POROne = on-prem-only) often have no marker on
// their lines because there's no other option. For those we fall back to a
// product-family default. Ambiguous families (Elite, Syrinx, Expert) return
// null when no line carries a signal — better to drop the field than guess.
const FAMILY_DEFAULT = {
  'Rental Essentials': 'Cloud',
  'Record360': 'Cloud',
  'POROne': 'On-Prem',
};

function classifyLine(line) {
  const p = line && line.Product2;
  if (!p) return null;
  const dt = p.Deployment_Type__c;
  if (dt === 'Cloud' || dt === 'On-Prem') return dt;
  const name = p.Name || '';
  // Match `(Cloud)` and `(On-Prem` (covers `(On-Prem)` and `(On-Premise)`).
  if (/\(Cloud\)/i.test(name)) return 'Cloud';
  if (/\(On-Prem/i.test(name)) return 'On-Prem';
  return null;
}

function lineItems(opp) {
  const oli = opp && opp.OpportunityLineItems;
  if (!oli) return [];
  if (Array.isArray(oli)) return oli;          // dry-run / fixture shape
  if (Array.isArray(oli.records)) return oli.records; // SF REST shape
  return [];
}

// The authoritative source on closed opps is SBQQ__Quote__c.Deployment_Type__c
// (a writable picklist). Opportunity.Deployment_Type__c is a formula reading
// TEXT(SBQQ__PrimaryQuote__r.Deployment_Type__c) — both null when the rep
// didn't set the picklist on the Quote. We surface either as an explicit signal.
function explicitSignal(opp) {
  const oppLevel = opp.Deployment_Type__c;
  if (oppLevel === 'Cloud' || oppLevel === 'On-Prem') return oppLevel;
  const quoteLevel = opp?.SBQQ__PrimaryQuote__r?.Deployment_Type__c;
  if (quoteLevel === 'Cloud' || quoteLevel === 'On-Prem') return quoteLevel;
  return null;
}
function deploymentModel(opp) {
  if (!opp) return null;
  const explicit = explicitSignal(opp);
  if (explicit) return explicit;

  const signals = new Set();
  for (const line of lineItems(opp)) {
    const sig = classifyLine(line);
    if (sig) signals.add(sig);
  }
  if (signals.size === 1) return [...signals][0];
  if (signals.size === 2) return 'Cloud + On-Prem';

  // No line-item signal — fall back only for products sold in a single mode.
  return FAMILY_DEFAULT[productLabel(opp)] || null;
}

// Whether to PATCH the SBQQ Primary Quote's Deployment_Type__c with our
// detected value. Only when:
//   1. The Quote field is currently null (don't overwrite a rep's choice)
//   2. The Opportunity is New Business or Migration (the types where this
//      field is meaningful for downstream impl + reporting)
//   3. We detected a single-value signal (not "Cloud + On-Prem", not null)
//   4. There is a Primary Quote ID to patch
function shouldBackfillDeployment(opp) {
  if (!opp) return false;
  if (opp.Type !== 'New Business' && opp.Type !== 'Migration') return false;
  if (!opp.SBQQ__PrimaryQuote__c) return false;
  const quoteVal = opp?.SBQQ__PrimaryQuote__r?.Deployment_Type__c;
  if (quoteVal === 'Cloud' || quoteVal === 'On-Prem') return false;
  const detected = deploymentModel(opp);
  return detected === 'Cloud' || detected === 'On-Prem';
}


