// Multi-dimensional sales-cycle / ACV / user / location benchmarks.
// Computed from 10,831 closed opps in the trailing 365 days
// (5,534 won + 5,297 lost;
//  Type='Renewal' and StageName='Expired' excluded — Renewals are filtered before
//  this workflow ever fires, so their distribution is irrelevant to comparisons).
// Refresh quarterly via `node scripts/compute-benchmarks.mjs`.
//
// Methodology change (2026-05-06): baseline now includes Closed-Lost rows so
// medians reflect the time-to-close of the full deal population, not just
// won survivors. Renewals dropped entirely. Primary lookup is the 3-dim
// Region / Type / Product bucket — replaces the old multi-Type rotation hack.
//
// Lookup order (most specific wins, see pickBenchmark below):
//   1. byRegionTypeProduct — e.g. "US / New Business / Rental Essentials"  PRIMARY
//   2. byTypeProduct       — e.g. "Migration / Rental Elite"
//   3. byTypeSource        — e.g. "New Business / Web"
//   4. byRegionType        — e.g. "US / Migration"
//   5. byProduct           — e.g. "Rental Elite"
//   6. byType              — e.g. "Migration"
//   7. bySource            — e.g. "Marketing: Organic"
//   8. byPortfolio         — POR vs R360
//   9. byRegion            — US/UK/AU/Other
//
// LeadSource caveat: the bulk of opps have NULL LeadSource, so the bySource
// benchmark only meaningfully reflects the tagged minority. Surface as a
// data-quality note to GTM if it ever drives strategy.
const SF_BENCHMARKS = {
  computedAt: '2026-05-06',
  windowDays: 365,
