parameters.jsCode:
const exec = $json.execution || {};
const err = exec.error || $json.error || {};
const wfName = $json.workflow?.name || exec.workflowData?.name || 'sf-wins-notification';
const execId = exec.id || $json.id || '';
const execUrl = exec.url || '';
return [{
  json: {
    text: `:rotating_light: *${wfName}* failed:\n\n` +
          `Node: ${err?.node?.name || '(unknown)'}\n` +
          `Message: ${err?.message || JSON.stringify(err).slice(0,500)}\n` +
          (execUrl ? `Execution: <${execUrl}|${execId}>\n` : (execId ? `Execution: ${execId}\n` : '')) +
          `Time: ${new Date().toISOString()}`
  }
}];

const opps = $('Salesforce Query').all().map(i => i.json);
const lookup = $('Lookup Posted Rows').first();
const rows = (lookup && lookup.json && Array.isArray(lookup.json.data)) ? lookup.json.data : [];
const byOppId = Object.create(null);
for (const r of rows) {
  if (r && r.oppId) byOppId[r.oppId] = r;
}
const fresh = opps.filter(o => {
  const row = byOppId[o.Id];
  if (!row) return true; // never posted — keep
  const winsDone  = row.winsTs  && String(row.winsTs).length  > 0;
  const alertDone = row.alertTs && String(row.alertTs).length > 0;
  // Drop only if FULLY posted on both channels. Opps with one leg open
  // pass through and get re-checked per-item below.
  if (winsDone && alertDone) return false;
  return true;
});
return fresh.map(json => ({ json }));

const opps = $input.all().map(i => i.json);
const accountIds = [...new Set(opps.map(o => o.AccountId || (o.Account && o.Account.Id)).filter(Boolean))];
if (accountIds.length === 0) {
  return [{ json: {
    taskSoql: "SELECT Id FROM Task WHERE Id = NULL",
    eventSoql: "SELECT Id FROM Event WHERE Id = NULL",
    priorWinsSoql: "SELECT Id FROM Opportunity WHERE Id = NULL",
  } }];
}
const inClause = accountIds.map(id => "'" + String(id).replace(/[^A-Za-z0-9]/g,'') + "'").join(',');

// Dynamic backfill window: pull activity all the way back to the OLDEST
// opp.CreatedDate in the batch — minus an extra ACTIVITY_LOOKBACK_DAYS so
// the SOQL window matches engagement.js's pre-opp prospecting window. If
// engagement counts Apr-22 demos for an Apr-29 opp, the SOQL has to pull
// them in the first place. Keep this constant in sync with engagement.js.
// Falls back to a hard 730-day (2-year) safety cap when CreatedDate is missing.
const ACTIVITY_LOOKBACK_DAYS = 14;
let oldest = null;
for (const o of opps) {
  if (!o.CreatedDate) continue;
  const d = String(o.CreatedDate).slice(0, 10);
  if (!oldest || d < oldest) oldest = d;
}
if (oldest) {
  const t = new Date(oldest + 'T00:00:00Z').getTime();
  oldest = new Date(t - ACTIVITY_LOOKBACK_DAYS * 86400000).toISOString().slice(0, 10);
}
const safetyCap = new Date();
safetyCap.setDate(safetyCap.getDate() - 730); // hard 2-year max — keeps SF query bounded
const safetyCapStr = safetyCap.toISOString().slice(0, 10);
const startDate = (oldest && oldest > safetyCapStr) ? oldest : safetyCapStr;
const dateClause = "ActivityDate >= " + startDate;

const taskSoql = "SELECT Id, AccountId, WhatId, TaskSubtype, Type, Activity_Type__c, Status, Subject, ActivityDate, CreatedDate, CompletedDateTime, Completed_Date_Time__c, WhoId, CallType, OwnerId, " +
  "TYPEOF Owner WHEN User THEN Name, Email, Profile.Name, UserRole.Name, Department, Title, Record360_User__c, Slack_ID__c ELSE Name END, " +
  "Gong__Gong_Activity_Id__c, Gong__Meeting_Prospect_Canceled__c, Outreach_Attributed_Sequence_Name__c, Outreach_State__c " +
  "FROM Task WHERE AccountId IN (" + inClause + ") AND IsDeleted=FALSE AND Status='Completed' AND " + dateClause + " ORDER BY ActivityDate DESC LIMIT 5000";

const eventSoql = "SELECT Id, AccountId, WhatId, Subject, Type, EventSubtype, Activity_Type__c, ActivityDate, ActivityDateTime, Location, StartDateTime, EndDateTime, WhoId, OwnerId, " +
  "TYPEOF Owner WHEN User THEN Name, Email, Profile.Name, UserRole.Name, Department, Title, Record360_User__c, Slack_ID__c ELSE Name END, " +
  "Gong__Gong_Activity_Id__c, Gong__Meeting_Prospect_Canceled__c " +
  "FROM Event WHERE AccountId IN (" + inClause + ") AND IsDeleted=FALSE AND " + dateClause + " ORDER BY ActivityDate DESC LIMIT 5000";

// Aggregate count of prior wins per Account, split by portfolio
// (POR_Record__c / R360_Record__c). We count each portfolio separately so the
// "X prior wins" line in the History field only counts wins of the same flavor
// — POR opps see prior POR wins, R360 opps see prior R360 wins.
const priorWinsSoql = "SELECT AccountId, POR_Record__c, R360_Record__c, COUNT(Id) cnt " +
  "FROM Opportunity " +
  "WHERE AccountId IN (" + inClause + ") AND IsWon=TRUE AND IsClosed=TRUE " +
  "GROUP BY AccountId, POR_Record__c, R360_Record__c";

return [{ json: { taskSoql, eventSoql, priorWinsSoql } }];

// CRITICAL: source from Drop Already-Posted (post-dedup) not Salesforce Query.
// Sourcing from Salesforce Query was the 2026-05-04 dedup-bypass bug — the
// Merge silently re-resurrected already-posted opps, causing duplicate posts
// every 3 minutes. Re-apply the Renewal filter inline because Skip Renewals
// is also bypassed by named-node references.
const opps = $('Drop Already-Posted').all()
  .map(i => i.json)
  .filter(o => o && o.Type !== 'Renewal');
const acctTasks  = $('Account Tasks').all().map(i => i.json).filter(t => t && t.Id);
const acctEvents = $('Account Events').all().map(i => i.json).filter(e => e && e.Id);
const winRows    = $('Account Prior Wins').all().map(i => i.json).filter(w => w && w.AccountId);

const tasksByAcct = new Map();
for (const t of acctTasks) {
  if (!t.AccountId) continue;
  if (!tasksByAcct.has(t.AccountId)) tasksByAcct.set(t.AccountId, []);
  tasksByAcct.get(t.AccountId).push(t);
}
const eventsByAcct = new Map();
for (const e of acctEvents) {
  if (!e.AccountId) continue;
  if (!eventsByAcct.has(e.AccountId)) eventsByAcct.set(e.AccountId, []);
  eventsByAcct.get(e.AccountId).push(e);
}
// Aggregate row shape: { AccountId, POR_Record__c, R360_Record__c, cnt }.
// jsforce drops 'cnt' in favor of 'expr0' on aggregate queries — accept either.
const winsByAcct = new Map();
for (const w of winRows) {
  const aid = w.AccountId;
  if (!winsByAcct.has(aid)) winsByAcct.set(aid, { por: 0, r360: 0, total: 0 });
  const bucket = winsByAcct.get(aid);
  const c = w.cnt ?? w.expr0 ?? 0;
  if (w.POR_Record__c) bucket.por += c;
  if (w.R360_Record__c) bucket.r360 += c;
  bucket.total += c;
}

return opps.map(opp => {
  const aid = opp.AccountId || (opp.Account && opp.Account.Id);
  const oppTaskIds  = new Set((opp.Tasks  && opp.Tasks.records  || []).map(t => t.Id));
  const oppEventIds = new Set((opp.Events && opp.Events.records || []).map(e => e.Id));
  const extraTasks  = (tasksByAcct.get(aid)  || []).filter(t => !oppTaskIds.has(t.Id));
  const extraEvents = (eventsByAcct.get(aid) || []).filter(e => !oppEventIds.has(e.Id));
  // Pick the portfolio-scoped count: POR opps → POR wins, R360 opps →
  // R360 wins, else total. Mirrors Account.Num_Closed_Won_Opportunities__c
  // semantics (count includes current opp); the History field renders this
  // as "X prior wins" the same way it always has.
  const wins = winsByAcct.get(aid) || { por: 0, r360: 0, total: 0 };
  let scoped;
  if (opp.POR_Record__c === true) scoped = wins.por;
  else if (opp.R360_Record__c === true) scoped = wins.r360;
  else scoped = wins.total;
  return {
    json: {
      ...opp,
      Tasks:  { records: [...(opp.Tasks  && opp.Tasks.records  || []), ...extraTasks ] },
      Events: { records: [...(opp.Events && opp.Events.records || []), ...extraEvents] },
      Prior_Wins_Scoped__c: scoped,
    },
  };
});

// === win-classifier.js ===
// Classify Opportunity.Type → Slack template + region.
// Type picklist values (verified via sf sobject describe on Opportunity):
//   New Business, Existing Business, Migration, Consulting, Credit Card, Renewal, Reseller
const WIN_TYPES = {
  NEW_LOGO: 'new-logo',
  EXPANSION: 'expansion',
  MIGRATION: 'migration',
  UNKNOWN: 'unknown',
};
function classifyWinType(opp) {
  const t = opp.Type;
  if (t === 'New Business') return WIN_TYPES.NEW_LOGO;
  if (t === 'Existing Business' || t === 'Renewal') return WIN_TYPES.EXPANSION;
  if (t === 'Migration') return WIN_TYPES.MIGRATION;
  return WIN_TYPES.UNKNOWN;
}
function templateLabel(winType) {
  switch (winType) {
    case WIN_TYPES.NEW_LOGO: return 'New Logo WIN';
    case WIN_TYPES.EXPANSION: return 'Expansion Win';
    case WIN_TYPES.MIGRATION: return 'Migration WIN';
    default: return 'Win';
  }
}

const US_COUNTRIES = new Set([
  'United States', 'USA', 'US', 'U.S.', 'U.S.A.', 'United States of America',
]);
function isUS(opp) {
  const country = opp?.Account?.BillingCountry?.trim();
  if (!country) return false;
  return US_COUNTRIES.has(country);
}


// === format-helpers.js ===
// Format helpers: country flags, currency, tier banners, sales-cycle emoji.

const COUNTRY_FLAGS = {
  'United States': ':flag-us:', 'USA': ':flag-us:', 'US': ':flag-us:',
  'United Kingdom': ':flag-gb:', 'UK': ':flag-gb:', 'England': ':flag-gb:',
  'Scotland': ':flag-gb:', 'Wales': ':flag-gb:', 'Northern Ireland': ':flag-gb:',
  'Australia': ':flag-au:',
  'Canada': ':flag-ca:',
  'Ireland': ':flag-ie:',
  'New Zealand': ':flag-nz:',
  'Germany': ':flag-de:',
  'France': ':flag-fr:',
  'Spain': ':flag-es:',
  'Italy': ':flag-it:',
  'Mexico': ':flag-mx:',
  'Netherlands': ':flag-nl:',
  'Belgium': ':flag-be:',
  'Sweden': ':flag-se:',
  'Norway': ':flag-no:',
  'Denmark': ':flag-dk:',
  'Finland': ':flag-fi:',
  'Puerto Rico': ':flag-pr:',
};
function flagFor(country) {
  if (!country) return ':globe_with_meridians:';
  const trimmed = country.trim();
  return COUNTRY_FLAGS[trimmed] || ':globe_with_meridians:';
}

const CURRENCY_SYMBOLS = {
  USD: '$', GBP: '£', EUR: '€', CAD: 'CA$', AUD: 'A$',
  NZD: 'NZ$', JPY: '¥', CHF: 'CHF ', SEK: 'kr', NOK: 'kr', DKK: 'kr',
  MXN: 'MX$', BRL: 'R$', INR: '₹',
};

// Symbol-only money format. The currency symbol disambiguates (CA$ ≠ A$ ≠ $),
// so trailing ISO codes like " USD" are redundant and dropped. Whole-dollar
// values drop trailing .00 — keeps the line clean and readable.
//   formatMoney(3818.76, 'USD')  → "$3,818.76"
//   formatMoney(80150,   'CAD')  → "CA$80,150"
//   formatMoney(0,       'USD')  → "$0"
function formatMoney(amount, isoCode) {
  if (amount === null || amount === undefined) return 'N/A';
  const sym = CURRENCY_SYMBOLS[isoCode] ?? '';
  const abs = Math.abs(amount);
  const isWhole = Math.round(abs) === abs;
  const formatted = abs.toLocaleString('en-US', {
    minimumFractionDigits: isWhole ? 0 : 2,
    maximumFractionDigits: 2,
  });
  return `${amount < 0 ? '-' : ''}${sym}${formatted}`;
}

// Pulls the USD-equivalent of the Opp's annual ACV (with downpayment).
// Prefers ACV_with_Downpayment_Corporate_Currency__c, the SF formula that
// divides Annual_Contract_Value_with_Downpayment__c by CURRENCYRATE — i.e. the
// USD value of the actual annual ACV.
//
// The older ACV_in_USD__c formula divides Annual_Contract_Value__c (≈ Amount,
// the multi-year contract total) instead, which inflates the USD figure by 10x+
// on multi-year deals. We fall back to it only for fixtures/legacy callers
// that haven't been re-recorded with the corrected field.
function acvUsd(opp) {
  if (!opp) return null;
  const corp = opp.ACV_with_Downpayment_Corporate_Currency__c;
  if (corp != null) return corp;
  return opp.ACV_in_USD__c ?? null;
}

// Native first, then a softer USD comparison only when foreign.
// USD comparison is rounded to whole dollars (it's an approximation, not the contract value).
//   USD opp: "$3,818.76"
//   GBP opp: "£2,591.90 ≈ $3,281"
//   CAD opp: "CA$80,150.40 ≈ $59,814"
function formatAcv(opp) {
  const native = opp.Annual_Contract_Value_with_Downpayment__c;
  const usd = acvUsd(opp);
  const iso = opp.CurrencyIsoCode || 'USD';
  if (iso === 'USD' || native == null) return formatMoney(native ?? usd, 'USD');
  const usdRounded = usd != null ? Math.round(usd) : null;
  const usdPart = usdRounded != null ? ` ≈ ${formatMoney(usdRounded, 'USD')}` : '';
  return `${formatMoney(native, iso)}${usdPart}`;
}

// Color sidebar (Slack attachment.color) — matches the PRODUCT being sold so
// the channel reads at-a-glance: "oh that's a Record360 deal" by color alone.
// Whale tier ($100K+) gold-overrides for the rare big-fish moments.
//
// Brand colors verified by crawling https://www.point-of-rental.com CSS:
//   Syrinx             — green   #81BD41   (POR's signature lime-green)
//   Rental Elite       — orange  #F68623
//   Rental Expert      — red     #E32B2B
//   Record360          — red     #E32B2B   (per Kirk's brand mapping)
//   Inspect360         — red     #E32B2B   (R360 family)
//   Rental Essentials  — blue    #0C75B9
//   POROne             — black   #231F20   (off-black, brand-dark)
const COLORS_BY_PRODUCT = {
  'Rental Elite':      '#F68623',
  'Rental Essentials': '#0C75B9',
  'Rental Expert':     '#E32B2B',
  'Syrinx':            '#81BD41',
  'Record360':         '#E32B2B',
  'Inspect360':        '#E32B2B',
  'POROne':            '#231F20',
};

// Win-type colors are the floor when product is unknown / unmapped.
const COLORS_BY_WIN_TYPE = {
  'new-logo':  '#36b37e',
  'expansion': '#1f7ff5',
  'migration': '#8e5ed8',
  'unknown':   '#7d899c',
};
function sidebarColor(winType, acvUsd, productFamily) {
  if (acvUsd != null && acvUsd >= 100000) return '#f6ab2c'; // whale gold overrides
  if (productFamily && COLORS_BY_PRODUCT[productFamily]) return COLORS_BY_PRODUCT[productFamily];
  return COLORS_BY_WIN_TYPE[winType] || COLORS_BY_WIN_TYPE.unknown;
}

// Inline tier prefix folded into the headline (no separate banner block).
// Two tiers: BIG ($30K-$99.9K) and WHALE ($99.9K+). Sub-$30K wins get no
// prefix and rely on the per-win-type icon for visual identity.
function tierPrefix(acvUsd) {
  if (acvUsd == null) return null;
  if (acvUsd >= 99900) return ':lfg: WHALE :whale3:';
  if (acvUsd >= 30000) return 'BIG :strong-rocket:';
  return null;
}

// Tier word only (no emojis) — used in the bot username, where Slack renders
// the username as plain text (no emoji parsing).
function tierWord(acvUsd) {
  if (acvUsd == null) return null;
  if (acvUsd >= 99900) return 'WHALE';
  if (acvUsd >= 30000) return 'BIG';
  return null;
}

// @here mention only when the deal earns a tier (BIG+).
function shouldHerePing(acvUsd) {
  return acvUsd != null && acvUsd >= 30000;
}

// Auto-reaction emoji from Kirk's user token. Sub-tier deals get :rocket:,
// BIG+ deals get :lfg:. Threshold matches the @here / BIG WIN tier.
//   ACV < $30K USD  → :rocket:
//   ACV >= $30K USD → :lfg:
//   ACV null        → :rocket: (default — every win still gets a reaction)
// Returns the bare name (no colons) — Slack reactions.add expects "rocket"
// not ":rocket:".
function reactionEmoji(acvUsd) {
  if (acvUsd != null && acvUsd >= 30000) return 'lfg';
  return 'rocket';
}

// Sales-cycle quality emoji
function cycleEmoji(days) {
  if (days == null || isNaN(days)) return '';
  if (days < 0) return ':question:';
  if (days <= 7) return ':zap:';
  if (days <= 60) return ':dart:';
  if (days <= 180) return ':hourglass_flowing_sand:';
  return ':turtle:';
}

// Personality label for the sales cycle — pairs with cycleEmoji to give a sportscaster vibe.
// Multiple labels per bucket; hashIndex(oppId, n) picks deterministically so the same opp
// always renders the same label (test-stable).
//
// PRIMARY: band-keyed labels (peer-relative, comes from cycleBand). When the
// benchmark says a 16d deal in a 4d-median peer group is "veryLong", the
// cycle character should agree — "Patient close" not "Quick campaign". The
// label still pairs with the absolute (16d) suffix so the reader gets the
// raw cycle length too.
//
// FALLBACK: absolute-day buckets, used only when no benchmark band is
// available (e.g. a Type/Product combo we have no data for).
const BAND_CYCLE_LABELS = {
  veryFast: ['Lightning close', 'Surprise sprint', 'Flash result'],
  faster:   ['Ahead of pace', 'Quick close', 'Fast lane'],
  onPace:   ['On-pace close', 'Median run', 'Steady tempo'],
  longer:   ['Patient close', 'Steady grind', 'Earned grind'],
  veryLong: ['Long campaign', 'Patient saga', 'Distance run'],
};
const CYCLE_LABELS = {
  zero:       ['Same-day knockout'],
  week:       ['Same-week sprint', 'Lightning strike', 'Flash close', 'Blitz deal'],
  twoWeek:    ['Two-week tear', 'Quick win', 'Fast lane'],
  month:      ['Month closer', 'Solid push', 'Quick campaign'],
  sixWeek:    ['Six-week steady', 'Steady close', 'Tight campaign'],
  eightWeek:  ['Eight-week build', 'Steady grind', 'Patient push'],
  quarter:    ['Quarter-long campaign', 'Patient grind', 'Q campaign'],
  twoQuarter: ['Two-quarter saga', 'Six-month push', 'Long campaign'],
  halfYear:   ['Half-year hustle', 'Nine-month grind'],
  marathon:   ['Marathon', 'Year-long effort'],
  longHaul:   ['The long haul', 'Epic run'],
};
function cycleCharacter(days, oppId, band) {
  if (days == null || isNaN(days)) return null;
  if (days < 0) return 'Time-warp deal';
  // Band-aware path — keeps the cycle character aligned with the benchmark
  // tagline below it. Hash on `oppId + days` so the same opp + same band
  // always renders the same label (matching the bench tagline's hash key).
  if (band && BAND_CYCLE_LABELS[band]) {
    const labels = BAND_CYCLE_LABELS[band];
    return labels[hashIndex(`${oppId || ''}:${days}`, labels.length)];
  }
  let bucket;
  if (days === 0)   bucket = 'zero';
  else if (days <= 7)   bucket = 'week';
  else if (days <= 14)  bucket = 'twoWeek';
  else if (days <= 30)  bucket = 'month';
  else if (days <= 45)  bucket = 'sixWeek';
  else if (days <= 60)  bucket = 'eightWeek';
  else if (days <= 90)  bucket = 'quarter';
  else if (days <= 180) bucket = 'twoQuarter';
  else if (days <= 270) bucket = 'halfYear';
  else if (days <= 365) bucket = 'marathon';
  else                  bucket = 'longHaul';
  const labels = CYCLE_LABELS[bucket];
  return labels[hashIndex(oppId || '', labels.length)];
}

