function normalize(value) {
  return String(value || '').trim().toLowerCase();
}
function countryAbbreviation(country) {
  const trimmed = String(country || '').trim();
  if (!trimmed) return '';
  return COUNTRY_ABBREVIATIONS[normalize(trimmed)] || trimmed;
}
function regionAbbreviation(region) {
  const trimmed = String(region || '').trim();
  if (!trimmed) return '';
  if (/^[A-Z]{2,3}$/.test(trimmed)) return trimmed;
  return REGION_ABBREVIATIONS[normalize(trimmed)] || trimmed;
}
function headlineLocation(opp) {
  const account = opp?.Account || {};
  const region = regionAbbreviation(account.BillingState);
  const country = countryAbbreviation(account.BillingCountry);
  return [region, country].filter(Boolean).join(', ');
}
function leadHeadline({
  headerLabel,
  tierPrefix,
  acv,
  product,
  emoji,
  account,
  location,
  flag,
  mrkdwn = true,
}) {
  const label = headerLabel || 'Win';
  const accountName = account || 'an account';
  const productPart = product ? ` ${product}${emoji ? ` ${emoji}` : ''}` : '';
  const locationPart = location ? ` in ${location}` : '';
  const flagPart = flag ? ` ${flag}` : '';
  const fullLabel = tierPrefix ? `${tierPrefix} ${label}` : label;

  if (!mrkdwn) {
    return `${fullLabel}: ${acv} ACV${productPart} for ${accountName}${locationPart}${flagPart}`;
  }

  return `*${fullLabel}:* *${acv} ACV*${productPart} for *${accountName}*${locationPart}${flagPart}`;
}


