// Map countries → region (mirror of build-time logic)
const REGION_BY_COUNTRY = {
  'United States': 'US', 'USA': 'US', 'US': 'US',
  'United Kingdom': 'UK', 'UK': 'UK', 'England': 'UK',
  'Scotland': 'UK', 'Wales': 'UK', 'Northern Ireland': 'UK',
  'Australia': 'AU',
};

// Portfolio classification
const PORTFOLIO_BY_PRODUCT = {
  'Rental Elite': 'POR', 'Rental Essentials': 'POR', 'Rental Expert': 'POR',
  'Syrinx': 'POR', 'POROne': 'POR',
  'Record360': 'R360', 'Inspect360': 'R360',
};

// Pick the most specific benchmark bucket that has a meaningful median.
// Skips degenerate 0-day medians (Consulting / in-app-request buckets that
// auto-close same-day). Floor: >0d.
//
// `dealType` is the raw SF Opportunity.Type (New Business / Existing Business
// / Migration / Credit Card / Consulting). Renewals are filtered before this
// workflow ever fires, so the rotation hack that previously preferred
// Renewal-flavored medians is gone — the actual SF Type is the only one
// consulted. The "Expansion" display label collapses Existing Business
// (the only "expansion" type in the live data) for headline alignment.
//
// Lookup order (most specific first):
//   1. byRegionTypeProduct — primary, e.g. "US / Existing Business / Rental Elite"
//   2. byTypeProduct       — e.g. "Migration / Rental Elite"
//   3. byTypeSource        — e.g. "New Business / Web" (only when LeadSource set)
//   4. byRegionType        — e.g. "US / Migration"
//   5. byType              — e.g. "Migration"
//   6. byProduct           — fallback; drops deal type from label
//   7. bySource            — when LeadSource set
//   8. byPortfolio         — POR vs R360
//   9. byRegion            — final fallback
function pickBenchmark({ winType, dealType, productFamily, country, leadSource }) {
  const TYPE_BY_SLUG = {
    'new-logo': 'New Business',
    'expansion': 'Existing Business',
    'migration': 'Migration',
  };
  // Display label: "Existing Business" reads as "Expansion" so the benchmark
  // scope matches the headline ("Expansion WIN" → "Expansion / Rental Elite").
  // Other types pass through unchanged.
  const TYPE_DISPLAY = {
    'New Business':      'New Business',
    'Existing Business': 'Expansion',
    'Migration':         'Migration',
  };
  const displayType = (sfType) => TYPE_DISPLAY[sfType] || sfType;
  const sfType = dealType || TYPE_BY_SLUG[winType] || null;
  const region = REGION_BY_COUNTRY[(country || '').trim()] || 'Other';
  const portfolio = PORTFOLIO_BY_PRODUCT[productFamily];

  const candidates = [];

  // 1. PRIMARY: Region / Type / Product — the most granular peer group.
  if (sfType && productFamily && region) {
    const k = `${region} / ${sfType} / ${productFamily}`;
    if (SF_BENCHMARKS.byRegionTypeProduct[k]) {
      const labelK = region === 'Other'
        ? `${displayType(sfType)} / ${productFamily}`
        : `(${region}) ${displayType(sfType)} / ${productFamily}`;
      candidates.push({ ...SF_BENCHMARKS.byRegionTypeProduct[k], scope: labelK });
    }
  }
  // 2. Type × Product — drops region but keeps the deal-type/product pair.
  if (sfType && productFamily) {
    const k = `${sfType} / ${productFamily}`;
    if (SF_BENCHMARKS.byTypeProduct[k]) {
      const labelK = `${displayType(sfType)} / ${productFamily}`;
      const scope = region && region !== 'Other' ? `(${region}) ${labelK}` : labelK;
      candidates.push({ ...SF_BENCHMARKS.byTypeProduct[k], scope });
    }
  }
  // 3. Type × Source — narrows by GTM motion (when LeadSource present)
  if (sfType && leadSource) {
    const k = `${sfType} / ${leadSource}`;
    if (SF_BENCHMARKS.byTypeSource[k]) {
      const labelK = `${displayType(sfType)} / ${leadSource}`;
      const scope = region && region !== 'Other' ? `(${region}) ${labelK}` : labelK;
      candidates.push({ ...SF_BENCHMARKS.byTypeSource[k], scope });
    }
  }
  // 4. Region × Type — geo-anchored, drops product
  if (sfType && region) {
    const k = `${region} / ${sfType}`;
    if (SF_BENCHMARKS.byRegionType[k]) {
      candidates.push({ ...SF_BENCHMARKS.byRegionType[k], scope: `${region} / ${displayType(sfType)}` });
    }
  }
  // Region prefix shared by all non-region-aggregated buckets.
  const rPrefix = region && region !== 'Other' ? `(${region}) ` : '';

  // 5. Type alone
  if (sfType && SF_BENCHMARKS.byType[sfType]) {
    candidates.push({ ...SF_BENCHMARKS.byType[sfType], scope: `${rPrefix}${displayType(sfType)} deals` });
  }
  // 6. Product alone — last resort that drops deal type from the label.
  if (productFamily && SF_BENCHMARKS.byProduct[productFamily]) {
    candidates.push({ ...SF_BENCHMARKS.byProduct[productFamily], scope: `${rPrefix}${productFamily}` });
  }
  // 7. Source alone
  if (leadSource && SF_BENCHMARKS.bySource[leadSource]) {
    candidates.push({ ...SF_BENCHMARKS.bySource[leadSource], scope: `${rPrefix}${leadSource}-sourced` });
  }
  // 8. Portfolio (POR vs R360)
  if (portfolio && SF_BENCHMARKS.byPortfolio[portfolio]) {
    candidates.push({ ...SF_BENCHMARKS.byPortfolio[portfolio], scope: `${rPrefix}${portfolio} portfolio` });
  }
  // 9. Region alone
  if (SF_BENCHMARKS.byRegion[region]) {
    candidates.push({ ...SF_BENCHMARKS.byRegion[region], scope: `${region} deals` });
  }
  return candidates.find(c => c.medianCycleDays > 0) || null;
}

// Live peer comparison — preferred over static when the workflow injects a
// peer set (last 25 closed-won opps matching Type+Product). Returns a single
// rank-style line:
//   "Faster than 22 of last 25 New Business / Rental Essentials deals (median: 36d)"
//   "Slower than 18 of last 25 …"
// Returns null when peer set < 5 (too noisy) or current is within ±1 day of median.
function cycleVsPeers({ days, peerCycles, scope }) {
  if (days == null || days <= 0) return null;
  if (!Array.isArray(peerCycles) || peerCycles.length < 5) return null;
  const valid = peerCycles.filter(d => d != null && d > 0).sort((a, b) => a - b);
  if (valid.length < 5) return null;
  const n = valid.length;
  const median = n % 2 ? valid[(n - 1) / 2] : (valid[n / 2 - 1] + valid[n / 2]) / 2;
  if (Math.abs(days - median) <= 1) return null;
  // Count peers strictly slower (cycle > current days) → that's how many we beat
  const peersSlower = valid.filter(d => d > days).length;
  const peersFaster = valid.filter(d => d < days).length;
  const med = Math.round(median);
  if (peersSlower > peersFaster) {
    return `*Faster than ${peersSlower} of last ${n}* ${scope} deals (median: ${med}d)`;
  }
  return `Slower than ${peersFaster} of last ${n} ${scope} deals (median: ${med}d)`;
}

// Static-benchmark fallback when no peer set was injected. Always returns a
// celebratory line — every band (faster / on-pace / longer) gets a unique
// positive-vibes tagline, picked deterministically per Opp via hashIndex.
//
// Five bands by ratio = days / median:
//   ≤ 0.5    very fast    (Nx faster) → :rocket: lightning vibes
//   ≤ 0.7    faster       (faster than typical)
//   < 1.4    on pace      (textbook timing)
//   < 2.0    longer       (steady grind)
//   ≥ 2.0    very long    (Nx longer) → marathon vibes
//
// Soft-median rule: when the bucket median is < 7d (admin-style fast-close
// peers like UK/Existing Business/Syrinx at 4d), suppress the "Nx" multiplier
// even on big deltas. "13.8x longer than typical 4d" reads as if the deal is
// broken when it's just slower than a peer set dominated by single-touch
// admin closes. The tagline still fires; the multiplier doesn't.
const SOFT_MEDIAN_FLOOR = 7;

const BENCH_TAGLINES = {
  veryFast: [
    ':checkered_flag: *Lightning close*',
    ':rocket: *Speedrun*',
    ':zap: *Velocity play*',
    ':fast_forward: *Closed in a flash*',
    ':stopwatch: *Cycle compressed*',
    ':motor_boat: *Hit the gas, hit the wire*',
  ],
  faster: [
    ':runner: *Ahead of pace*',
    ':airplane: *On the front foot*',
    ':dash: *Quicker than peers*',
    ':sun_with_face: *Sunny side of the median*',
    ':bicyclist: *Cruised past peers*',
    ':tropical_drink: *Closed before peers caught up*',
  ],
  onPace: [
    ':bullseye: *Textbook timing*',
    ':musical_note: *Right in rhythm*',
    ':white_check_mark: *On the typical beat*',
    ':dart: *Median-perfect close*',
    ':balance_scale: *Right where peers land*',
    ':gear: *Smooth median lap*',
  ],
  longer: [
    ':hammer: *Steady grind*',
    ':muscle: *Earned every day*',
    ':seedling: *Patience paid off*',
    ':trophy: *Worth the wait*',
    ':wrench: *Solid follow-through*',
    ':books: *Wrote the textbook on persistence*',
  ],
  veryLong: [
    ':mountain: *Marathon close*',
    ':crystal_ball: *Long-game played right*',
    ':ship: *Extended runway, landed*',
    ':telescope: *Played the long horizon*',
    ':tada: *Multi-quarter saga, won*',
    ':athletic_shoe: *Distance closer*',
  ],
};

// Hash on oppId + days so two same-band opps with different cycles land on
// different variants. Without the days component, three veryLong opps could
// all collide on the same tagline (the "everything was Marathon" problem).
function pickTagline(band, oppId, days) {
  const pool = BENCH_TAGLINES[band];
  const seed = `${oppId || ''}:${days ?? 0}`;
  return pool[hashIndex(seed, pool.length)];
}

// Band classification — exposed separately so other UI bits (like the cycle
// character label) can use the same peer-relative bucket the tagline does.
// Without this, the cycle character defaults to absolute-day buckets and can
// disagree with the tagline (e.g. 16d in a peer group with 4d median reads
// "Quick campaign" by absolute terms but is veryLong relative to peers).
function cycleBand({ winType, dealType, productFamily, country, leadSource, days }) {
  if (days == null || days <= 0) return null;
  const bench = pickBenchmark({ winType, dealType, productFamily, country, leadSource });
  if (!bench || !(bench.medianCycleDays > 0)) return null;
  const ratio = days / bench.medianCycleDays;
  if (ratio <= 0.5) return 'veryFast';
  if (ratio <= 0.7) return 'faster';
  if (ratio < 1.4)  return 'onPace';
  if (ratio < 2.0)  return 'longer';
  return 'veryLong';
}
function cycleVsBenchmark({ winType, dealType, productFamily, country, leadSource, days, oppId }) {
  if (days == null || days <= 0) return null;
  const bench = pickBenchmark({ winType, dealType, productFamily, country, leadSource });
  if (!bench) return null;
  const median = bench.medianCycleDays;
  const ratio = days / median;
  const softMedian = median < SOFT_MEDIAN_FLOOR;
  const med = formatMedian(median);
  const scope = bench.scope;
  let band, comparison;
  if (ratio <= 0.5) {
    band = 'veryFast';
    comparison = softMedian ? `faster than typical ${med}d ${scope}` : `*${(median / days).toFixed(1)}x faster* than typical ${med}d ${scope}`;
  } else if (ratio <= 0.7) {
    band = 'faster';
    comparison = `faster than typical ${med}d ${scope}`;
  } else if (ratio < 1.4) {
    band = 'onPace';
    comparison = `typical ${med}d ${scope}`;
  } else if (ratio < 2.0) {
    band = 'longer';
    comparison = `longer than typical ${med}d ${scope}`;
  } else {
    band = 'veryLong';
    comparison = softMedian ? `longer than typical ${med}d ${scope}` : `*${ratio.toFixed(1)}x longer* than typical ${med}d ${scope}`;
  }
  return `${pickTagline(band, oppId, days)} — ${comparison}`;
}

function formatMedian(n) {
  return Math.round(n).toString();
}


// === engagement.js ===

// Breaks down related Tasks + Events into a deduped, bucketed activity line.
//
// Sources we account for (verified against POR prod schema in /tmp/activity-research.md):
//   - Manual rep-entered Tasks/Events     (TaskSubtype Call/Email/Task)
//   - Outreach.io sequences                (Subject prefixed `[Outreach] [Email|Other] ...`)
//   - Gong call/meeting recordings         (`Gong__Gong_Activity_Id__c` non-null)
//   - Einstein Activity Capture / Google   (no SF Task/Event written -> invisible to SOQL)
//
// Filters before bucketing:
//   - Tasks: `Status === 'Completed'` only
//   - Events: canceled Gong/calendar meetings are skipped
//   - Activity must be owned by a deal-team member — combined whitelist of
//     the opp's Owner / AE__r / SDR__r / SalesEngineerEmail__c PLUS every
//     OpportunityTeamMember (collaborator) on the record. Drops the long
//     tail of Automated Process, marketing blasts, and tangentially-involved
//     reps that don't represent the team that closed the deal. The team
//     configuration is authoritative — we don't second-guess via portfolio
//     flags (e.g. an R360 rep listed as Owner on a POR-flagged opp still
//     counts; the team list reflects the truth on the ground).
//
// Dedup keys:
//   - Emails: canonical subject + activity date + contact + owner
//   - Meetings: canonical subject + start time (collapses Gong/calendar/attendee twins)
//   - Calls: same contact + owner + date within 10 minutes (collapses call Task/Event twins)

const OUTREACH_PREFIX = /^\[outreach\]\s*\[(?<kind>[^\]]+)\]\s*(?<rest>.*)$/i;
const LEADING_TAGS = /^(\s*\[[^\]]+\]\s*)+/;
// Cross-source dedup window: tight enough that distinct attempts within the
// same day stay separate (3 calls 30 minutes apart = 3 calls), wide enough
// that Outreach + EAC + Gong twins of the same physical send/call/meeting
// collapse to one. Emails drift more than calls because Outreach logs at
// sequence-fire time while EAC logs at actual-send time and the queue can
// add several minutes between them — so emails get a wider window.
const CROSS_SOURCE_DEDUP_WINDOW_MS = 5 * 60 * 1000;
const EMAIL_DEDUP_WINDOW_MS       = 10 * 60 * 1000;
// Activity window lookback: capture pre-opp prospecting touches. Many New
// Business deals see real customer engagement (demos, discovery calls)
// before the SF Opp record is even created. 14 days back from CreatedDate
// catches that pre-opp run-up without sweeping in unrelated history.
const ACTIVITY_LOOKBACK_DAYS = 14;
const ACTIVITY_LOOKBACK_MS = ACTIVITY_LOOKBACK_DAYS * 24 * 60 * 60 * 1000;

function stripOutreachPrefix(subject) {
  const m = String(subject || '').trim().match(OUTREACH_PREFIX);
  return m ? (m.groups.rest || '').trim() : String(subject || '').trim();
}

function canonicalSubject(subject) {
  let s = stripOutreachPrefix(subject)
    .replace(/^\[gong\]\s*/i, '')
    .replace(/^zoom:\s*/i, '')
    .replace(/^email:\s*/i, '')
    .replace(/^outbound email \(outreach\)\s*-\s*/i, '')
    .replace(/^call placed:\s*/i, '')
    .replace(LEADING_TAGS, '');
  // Strip nested Re:/RE:/Fwd:/FW: reply chains so same-thread replies share
  // a canonical key — collapses an email thread across days into a single
  // counted interaction.
  let prev;
  do {
    prev = s;
    s = s.replace(/^\s*(?:re|fw|fwd)\s*:\s*/i, '');
  } while (s !== prev);
  return s
    .replace(/\s+@\s+/g, ' ')
    .replace(/[^a-z0-9]+/gi, ' ')
    .trim()
    .toLowerCase();
}

function timestampMs(value) {
  if (!value) return null;
  const t = new Date(value).getTime();
  return Number.isNaN(t) ? null : t;
}

function taskTimestampMs(t) {
  return timestampMs(t.CompletedDateTime)
    ?? timestampMs(t.Completed_Date_Time__c)
    ?? timestampMs(t.CreatedDate);
}

function dateOnly(value) {
  return value ? String(value).slice(0, 10) : '';
}

function eventBucket(e) {
  const subj = e.Subject || '';
  const typeBlob = `${e.Type || ''} ${e.EventSubtype || ''} ${e.Activity_Type__c || ''}`;
  if (/\bcall\b/i.test(typeBlob) || /^call with\b/i.test(subj)) return 'calls';
  return 'meetings';
}

// Categorize one task. Returns the bucket name OR `null` to SKIP the record
// entirely. LinkedIn and generic notes/tasks do not represent direct engagement,
// and demos are meetings for reporting purposes.
function classifyTask(t) {
  const rawSubj = t.Subject || '';
  const subj = rawSubj.toLowerCase();
  const sub = (t.TaskSubtype || '').toLowerCase();
  const type = (t.Type || '').toLowerCase();
  const actType = (t.Activity_Type__c || '').toLowerCase();

  // 1. Outreach `[Outreach] [Other]` subjects — re-parse the post-prefix subject
  const m = rawSubj.match(OUTREACH_PREFIX);
  if (m && /other/i.test(m.groups.kind || '')) {
    const rest = (m.groups.rest || '').toLowerCase();
    if (/linkedin|\bli\b/.test(rest))        return null;  // SKIP — usually auto-completed
    if (/voicemail|voice.?mail/.test(rest)) return 'calls';
    if (/\bcall\b/.test(rest))               return 'calls';
    if (/text|sms/.test(rest))               return 'texts';
    if (/\bdemo\b/.test(rest))               return 'meetings';
    return null;
  }
  if (m && /email/i.test(m.groups.kind || '')) return 'emails';

  // 2. Activity_Type__c custom picklist (more reliable than Type for manual)
  if (actType) {
    if (/linkedin|\bli\b/.test(actType)) return null;  // SKIP
    if (/call/.test(actType)) return 'calls';
    if (/email/.test(actType)) return 'emails';
    if (/demo/.test(actType)) return 'meetings';
    if (/meeting/.test(actType)) return 'meetings';
  }

  // 3. Subject keyword skip — any LinkedIn-tagged task drops out before the
  // standard subtype/type fallback can pick it up.
  if (/linkedin|\bli\b/.test(subj)) return null;

  // 4. Standard SF TaskSubtype + Type
  if (sub === 'call' || /call|inbound|outbound|cold/.test(type)) return 'calls';
  if (sub === 'email' || /email/.test(type)) return 'emails';

  // 5. Subject-keyword fallback for legacy/manual tasks
  if (/\bdemo\b/.test(subj)) return 'meetings';
  if (/meeting|sync|check.?in|kickoff/.test(subj) || /meeting/.test(type)) return 'meetings';
  if (/\btext\b|sms/.test(subj)) return 'texts';
  return null;
}

// Strict whitelist of every email tied to the deal team, drawn from BOTH:
//   1. Hard-coded fields: Owner, AE__r, SDR__r, SalesEngineerEmail__c
//   2. Dynamic OpportunityTeamMembers (the official "collaborator" object) —
//      catches roles like Account Manager that aren't in the four hardcoded
//      slots but are still credited collaborators on the opp.
// Any activity whose Owner.Email is outside this combined set is dropped.
function dreamTeamEmails(opp) {
  const emails = [
    opp?.Owner?.Email,
    opp?.AE__r?.Email,
    opp?.SDR__r?.Email,
    opp?.SalesEngineerEmail__c,
  ];
  for (const m of opp?.OpportunityTeamMembers?.records || []) {
    if (m?.User?.Email) emails.push(m.User.Email);
  }
  return new Set(
    emails.filter(Boolean).map(s => String(s).toLowerCase()),
  );
}

function ownedByTeamMember(team, activity) {
  const email = activity?.Owner?.Email ? String(activity.Owner.Email).toLowerCase() : '';
  if (!email) return false;
  return team.has(email);
}

function toTaskInteraction(t) {
  const bucket = classifyTask(t);
  if (!bucket) return null;
  return {
    source: 'Task',
    bucket,
    date: t.ActivityDate || dateOnly(t.CompletedDateTime || t.Completed_Date_Time__c || t.CreatedDate),
    time: taskTimestampMs(t),
    ownerName: t.Owner?.Name || '',
    ownerEmail: String(t.Owner?.Email || '').toLowerCase(),
    ownerSlackId: t.Owner?.Slack_ID__c || '',
    who: t.WhoId || '',
    subject: t.Subject || '',
    canonicalSubject: canonicalSubject(t.Subject || ''),
  };
}

function toEventInteraction(e) {
  const start = e.StartDateTime || e.ActivityDateTime || e.ActivityDate;
  return {
    source: 'Event',
    bucket: eventBucket(e),
    date: dateOnly(start),
    time: timestampMs(start),
    ownerName: e.Owner?.Name || '',
    ownerEmail: String(e.Owner?.Email || '').toLowerCase(),
    ownerSlackId: e.Owner?.Slack_ID__c || '',
    who: e.WhoId || '',
    subject: e.Subject || '',
    canonicalSubject: canonicalSubject(e.Subject || ''),
  };
}

function sameKnownContact(a, b) {
  return !a.who || !b.who || a.who === b.who;
}

function hasStrongSubjectIdentity(interaction) {
  return Boolean(
    interaction.date
    && interaction.ownerEmail
    && interaction.who
    && interaction.canonicalSubject
  );
}

function isDuplicateInteraction(candidate, kept) {
  for (const prior of kept) {
    // Cross-source twin: same owner + same canonical subject + same bucket +
    // logged within the bucket-specific dedup window. This catches the
    // common case where Outreach, EAC, and Gong each log the same physical
    // email / call within minutes of each other. Distinct attempts (a
    // follow-up call 30 minutes after the first) survive — they're outside
    // the dedup window. Multi-day thread continuation also survives, since
    // each day produces a separate interaction.
    if (
      candidate.bucket === prior.bucket
      && candidate.bucket !== 'meetings'
      && candidate.ownerEmail && candidate.ownerEmail === prior.ownerEmail
      && candidate.canonicalSubject && candidate.canonicalSubject === prior.canonicalSubject
      && candidate.time != null && prior.time != null
      && Math.abs(candidate.time - prior.time) <= (
        candidate.bucket === 'emails' ? EMAIL_DEDUP_WINDOW_MS : CROSS_SOURCE_DEDUP_WINDOW_MS
      )
    ) return true;

    // Calls have an extra path: when the canonical subject is generic
    // ("Call", "Outbound", etc.) different sources may not match on subject
    // but still represent the same physical call. Match on (date + owner +
    // contact + ±5min time) regardless of subject.
    if (
      candidate.bucket === 'calls'
      && prior.bucket === 'calls'
      && candidate.date === prior.date
      && candidate.ownerEmail
      && candidate.ownerEmail === prior.ownerEmail
      && sameKnownContact(candidate, prior)
      && candidate.time != null
      && prior.time != null
      && Math.abs(candidate.time - prior.time) <= CROSS_SOURCE_DEDUP_WINDOW_MS
    ) return true;

    // Meetings: exact start time is the strongest signal. Two ways to match
    //   (a) same instant + same contact (WhoId) — covers EAC vs Gong twins
    //       where one calls it "Google Meet: X" and the other calls it "X"
    //   (b) same instant + same canonical subject — fallback when WhoId
    //       isn't populated (rare for meetings, but happens)
    // Same instant on the same opp/account is essentially never two
    // distinct meetings, so the strong (time, who) match is safe.
    if (
      candidate.bucket === 'meetings'
      && prior.bucket === 'meetings'
      && candidate.time != null
      && candidate.time === prior.time
      && (
        (candidate.who && prior.who && candidate.who === prior.who)
        || (candidate.canonicalSubject && candidate.canonicalSubject === prior.canonicalSubject)
      )
    ) return true;
  }

  return false;
}

function dedupeInteractions(interactions) {
  const kept = [];
  let dropped = 0;
  for (const interaction of interactions.sort((a, b) =>
    (a.time ?? 0) - (b.time ?? 0)
    || a.source.localeCompare(b.source)
    || a.canonicalSubject.localeCompare(b.canonicalSubject)
  )) {
    if (isDuplicateInteraction(interaction, kept)) {
      dropped++;
      continue;
    }
    kept.push(interaction);
  }
  return { kept, dropped };
}

function ownerKey(interaction) {
  return interaction.ownerEmail || interaction.ownerName || 'unknown';
}

function ownerLabel(interaction) {
  return interaction.ownerName || interaction.ownerEmail || 'Unknown owner';
}

function bucketCountParts(counts) {
  return [
    counts.calls > 0 && `${counts.calls} call${counts.calls === 1 ? '' : 's'}`,
    counts.emails > 0 && `${counts.emails} email${counts.emails === 1 ? '' : 's'}`,
    counts.meetings > 0 && `${counts.meetings} meeting${counts.meetings === 1 ? '' : 's'}`,
    counts.texts > 0 && `${counts.texts} text${counts.texts === 1 ? '' : 's'}`,
  ].filter(Boolean);
}

function ownerDetail(interactions) {
  if (!interactions.some(i => i.ownerName || i.ownerEmail)) return null;

  const grouped = new Map();
  for (const interaction of interactions) {
    const key = ownerKey(interaction);
    if (!grouped.has(key)) {
      grouped.set(key, {
        label: ownerLabel(interaction),
        slackId: interaction.ownerSlackId || '',
        calls: 0,
        emails: 0,
        meetings: 0,
        texts: 0,
        total: 0,
      });
    }
    const row = grouped.get(key);
    if (!row.slackId && interaction.ownerSlackId) row.slackId = interaction.ownerSlackId;
    row[interaction.bucket]++;
    row.total++;
  }

  const groups = [...grouped.values()]
    .sort((a, b) => b.total - a.total || a.label.localeCompare(b.label));
  if (groups.length === 0) return null;

  const visible = groups.length > 4 ? groups.slice(0, 3) : groups;
  if (groups.length > 4) {
    const other = groups.slice(3).reduce((acc, row) => {
      acc.calls += row.calls;
      acc.emails += row.emails;
      acc.meetings += row.meetings;
      acc.texts += row.texts;
      acc.total += row.total;
      return acc;
    }, { label: 'Other reps', slackId: '', calls: 0, emails: 0, meetings: 0, texts: 0, total: 0 });
    visible.push(other);
  }

  const total = groups.reduce((sum, row) => sum + row.total, 0);
  const details = visible.map(row =>
    `${slackMention(row.label, row.slackId || undefined)} ${row.total} (${bucketCountParts(row).join(', ')})`
  );

  return `:busts_in_silhouette: *Rep detail:* ${details.join('  ·  ')}  =  *${total}*`;
}

// Activity falls within the opp's CreatedDate→CloseDate window.
// SF stores ActivityDate as YYYY-MM-DD; CreatedDate as a full ISO timestamp;
// CloseDate as YYYY-MM-DD. We compare on date strings to avoid timezone noise.
// Activities without any usable date are kept (defensive — better to overcount
// than silently drop).
function activityWithinWindow(activity, openIso, closeIso) {
  const openDate = openIso ? String(openIso).slice(0, 10) : null;
  const closeDate = closeIso ? String(closeIso).slice(0, 10) : null;
  const aDate = activity.ActivityDate
    || dateOnly(activity.CompletedDateTime)
    || dateOnly(activity.Completed_Date_Time__c)
    || dateOnly(activity.StartDateTime)
    || dateOnly(activity.ActivityDateTime)
    || dateOnly(activity.CreatedDate);
  if (!aDate) return true;
  if (openDate && aDate < openDate) return false;
  if (closeDate && aDate > closeDate) return false;
  return true;
}

// Returns the COUNTS object — the formatter (engagementSection) decides layout.
//   - Only Completed tasks count (open/deferred/in-progress are skipped)
//   - LinkedIn / generic notes return classifyTask=null and don't count at all
//   - Demos count as meetings; there is no separate demo bucket
//   - Marketing/Support/system-owned Tasks/Events are skipped
//   - Activities are scoped to the opp's CreatedDate→CloseDate window
//   - Raw counts (no cross-source dedup) — every recorded activity counts
function activityCounts(opp) {
  const tasksRaw = Array.isArray(opp.Tasks?.records) ? opp.Tasks.records : [];
  const eventsRaw = Array.isArray(opp.Events?.records) ? opp.Events.records : [];

  // Status filter (defense-in-depth — SOQL also restricts to Completed)
  const tasksDoneRaw = tasksRaw.filter(t =>
    !t.Status || String(t.Status).toLowerCase() === 'completed'
  );
  const tasksOpen = tasksRaw.length - tasksDoneRaw.length;

  const team = dreamTeamEmails(opp);
  // Extend window backward by ACTIVITY_LOOKBACK_DAYS so pre-opp prospecting
  // (discovery calls, demos before the SF Opp was opened) counts toward the
  // engagement story.
  const windowOpenIso = (() => {
    const t = timestampMs(opp.CreatedDate);
    return t == null ? opp.CreatedDate : new Date(t - ACTIVITY_LOOKBACK_MS).toISOString();
  })();
  const inWindow = a => activityWithinWindow(a, windowOpenIso, opp.CloseDate);
  const tasksOwned = tasksDoneRaw.filter(t => ownedByTeamMember(team, t) && inWindow(t));
  const tasksNotOnTeam = tasksDoneRaw.length - tasksOwned.length;

  // Window filter FIRST so out-of-window events (e.g. future recurring
  // catch-up meetings auto-canceled by Gong long after close) don't leak
  // into the "N canceled meetings skipped" footer. Only events that fell
  // inside the opp's create→close window can have meaningfully been
  // canceled relative to *this deal*.
  const eventsInWindow = eventsRaw.filter(inWindow);
  const eventsKept = eventsInWindow.filter(e => {
    if (e.Gong__Meeting_Prospect_Canceled__c === true) return false;
    if (/meeting\s+canceled/i.test(e.Subject || '')) return false;
    return true;
  });
  const eventsCanceled = eventsInWindow.length - eventsKept.length;

  const eventsOwned = eventsKept.filter(e => ownedByTeamMember(team, e));
  const eventsNotOnTeam = eventsKept.length - eventsOwned.length;
  const notOnTeamSkipped = tasksNotOnTeam + eventsNotOnTeam;

  let taskInteractionsSkipped = 0;
  const taskInteractions = [];
  for (const t of tasksOwned) {
    const interaction = toTaskInteraction(t);
    if (!interaction) {
      taskInteractionsSkipped++;
      continue;
    }
    taskInteractions.push(interaction);
  }
  const eventInteractions = eventsOwned.map(toEventInteraction);
  // Cross-source dedup: collapse duplicates that Outreach / EAC / Gong each
  // log for the same real-world email, call, or meeting. Match key is
  // (bucket + date + owner + canonicalSubject) — relaxed from earlier WhoId-
  // gated logic so multi-source duplicates with differing WhoId still merge.
  const { kept: interactions, dropped: dupesFiltered } = dedupeInteractions([
    ...taskInteractions,
    ...eventInteractions,
  ]);

  let calls = 0, emails = 0, meetings = 0, texts = 0;
  // Pre-opp tracking: count activity that happened BEFORE the opp record
  // existed. High pre-opp counts on a short SF cycle = classic sandbag
  // pattern (rep worked the deal off-record, then created/closed the opp
  // same-day to keep it off forecast).
  const oppCreatedDate = dateOnly(opp.CreatedDate);
  let preOppCalls = 0, preOppEmails = 0, preOppMeetings = 0, preOppTexts = 0;
  let preOppEarliest = null;
  for (const i of interactions) {
    if (i.bucket === 'calls')         calls++;
    else if (i.bucket === 'emails')   emails++;
    else if (i.bucket === 'meetings') meetings++;
    else if (i.bucket === 'texts')    texts++;
    if (oppCreatedDate && i.date && i.date < oppCreatedDate) {
      if (i.bucket === 'calls')         preOppCalls++;
      else if (i.bucket === 'emails')   preOppEmails++;
      else if (i.bucket === 'meetings') preOppMeetings++;
      else if (i.bucket === 'texts')    preOppTexts++;
      if (!preOppEarliest || i.date < preOppEarliest) preOppEarliest = i.date;
    }
  }
  const total = calls + emails + meetings + texts;
  const preOppTotal = preOppCalls + preOppEmails + preOppMeetings + preOppTexts;
  return {
    calls, emails, meetings, texts, total,
    preOppCalls, preOppEmails, preOppMeetings, preOppTexts, preOppTotal, preOppEarliest,
    ownerDetail: ownerDetail(interactions),
    dupesFiltered, eventsCanceled, tasksOpen,
    taskInteractionsSkipped,
    notOnTeamSkipped,
  };
}

// Build a full-width section block for the message body — escapes the cramped
// 2-column field grid and renders the breakdown across multiple lines.
// Returns null when the opp has no recorded activity.
function engagementSection(opp) {
  const c = activityCounts(opp);
  if (c.total === 0) {
    const rollup = opp.Number_of_Touches_Calls_Emails__c;
    if (rollup != null && rollup > 0) {
      return {
        type: 'section',
        text: { type: 'mrkdwn', text: `${rollup} interactions recorded` },
      };
    }
    // Genuinely-zero activity: surface the gap explicitly instead of hiding
    // the section. Common for R360 deals (their reps work in tools that don't
    // sync to SF Tasks/Events) and the occasional manual close where Outreach
    // / Gong never fired. Naming it out loud doubles as a data-quality nudge.
    return {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: ':zero: *0 documented interactions* — no Outreach / Gong / Tasks logged on this opp',
      },
    };
  }

  const channels = [c.calls, c.emails, c.meetings, c.texts].filter(n => n > 0).length;
  const headline = `*${c.total}* completed interactions across *${channels}* channel${channels === 1 ? '' : 's'}`;

  // Two compact rows so each emoji+number combo gets some breathing room.
  const row1 = [
    c.calls    > 0 && `:i-phone: *${c.calls}* call${c.calls === 1 ? '' : 's'}`,
    c.emails   > 0 && `:email: *${c.emails}* email${c.emails === 1 ? '' : 's'}`,
    c.meetings > 0 && `:calendar: *${c.meetings}* meeting${c.meetings === 1 ? '' : 's'}`,
  ].filter(Boolean).join('  ·  ');
  const row2 = [
    c.texts  > 0 && `:gmail: *${c.texts}* text${c.texts === 1 ? '' : 's'}`,
  ].filter(Boolean).join('  ·  ');
  const repDetail = c.ownerDetail;

  // Filter footer — only surface canceled meetings (dedup/open/LinkedIn/
  // non-sales-owner skips happen silently per Kirk's preference).
  const filterLine = c.eventsCanceled > 0
    ? `_${c.eventsCanceled} canceled meeting${c.eventsCanceled === 1 ? '' : 's'} skipped_`
    : '';

  // Coach line — fun saying that scales with interaction intensity, surfaces
  // $/interaction, and nudges email volume (POR data: emails correlate with win rate).
  const coach = coachLine({ counts: c, acvUsd: acvUsd(opp), oppId: opp.Id });

  // Splitting the coach line into its own context block keeps the main
  // section short enough to avoid Slack's "Show more" collapse, and the
  // smaller context-block typography reads naturally as commentary on the
  // numbers above it.
  const text = [headline, row1, row2, repDetail, filterLine].filter(Boolean).join('\n');
  const blocks = [{ type: 'section', text: { type: 'mrkdwn', text } }];
  // Sandbag heuristic: short SF cycle (≤1d) with material pre-opp activity
  // (≥5 interactions) means the rep worked the customer for days before
  // creating the opp record, then flipped it Closed Won quickly. Surface so
  // managers can spot off-pipeline forecasting. Joined with the coach line
  // via newline (single context block) so Slack doesn't insert block-level
  // spacing between them — reads as a tight commentary on the numbers.
  const cycleDays = daysBetween(opp.CreatedDate, opp.CloseDate);
  const showSandbag = c.preOppTotal >= 5 && cycleDays != null && cycleDays <= 1;
  const contextLines = [coach, showSandbag ? sandbagFlag(c, opp) : null].filter(Boolean);
  if (contextLines.length > 0) {
    blocks.push({
      type: 'context',
      elements: [{ type: 'mrkdwn', text: contextLines.join('\n') }],
    });
  }
  return blocks;
}

function sandbagFlag(c, opp) {
  const parts = [
    c.preOppCalls    > 0 && `${c.preOppCalls} call${c.preOppCalls === 1 ? '' : 's'}`,
    c.preOppEmails   > 0 && `${c.preOppEmails} email${c.preOppEmails === 1 ? '' : 's'}`,
    c.preOppMeetings > 0 && `${c.preOppMeetings} meeting${c.preOppMeetings === 1 ? '' : 's'}`,
    c.preOppTexts    > 0 && `${c.preOppTexts} text${c.preOppTexts === 1 ? '' : 's'}`,
  ].filter(Boolean).join(' · ');
  const earliest = c.preOppEarliest ? formatDateLong(c.preOppEarliest).replace(/, \d{4}$/, '') : '';
  const created = opp.CreatedDate ? formatDateLong(opp.CreatedDate).replace(/, \d{4}$/, '') : '';
  return `:warning: *Pre-opp activity:* ${parts} logged before opp existed (earliest ${earliest} · opp opened ${created} → closed same-day)`;
}


// === slack-blocks.js ===
// Build Slack Block Kit messages for Closed Won wins.
// Block Kit reference: https://api.slack.com/reference/block-kit/blocks
//
// Design rules:
//  - NEVER show a field with no value. If a value is null/empty/undefined,
//    that field is omitted. If every field in a section is empty, the entire
//    section (heading + fields) is omitted.
//  - Avoid repeating the same data twice (no people row in headline since
//    Dream Team section already shows them).






// Per-deal Slack bot identity. Each post is re-skinned so the channel reads
// "Migration WIN posted X" or "BIG Expansion WIN posted Y" — making the message
// type scannable from the username alone before reading any blocks.
//
//   Username = "[TIER ]{Type} WIN"     e.g. "Expansion WIN", "BIG Migration WIN"
//   Icon     = tier-specific (BIG = :rocket:, WHALE = :super-bowl-trophy:)
//              OR win-type-specific (sub-$30K, no tier):
//                new-logo  → :winning:
//                expansion → :star:
//                migration → :trophy:
const WIN_TYPE_LABELS = {
  [WIN_TYPES.NEW_LOGO]:  'New Business',
  [WIN_TYPES.EXPANSION]: 'Expansion',
  [WIN_TYPES.MIGRATION]: 'Migration',
};
// Sub-$30K bot icons by win type — these only show when no tier prefix is set.
const WIN_TYPE_ICONS = {
  [WIN_TYPES.NEW_LOGO]:  ':winning:',
  [WIN_TYPES.EXPANSION]: ':star:',
  [WIN_TYPES.MIGRATION]: ':trophy:',
};
// Tier-specific bot icons. BIG ($30K-$99.9K) gets :rocket:; WHALE ($99.9K+)
// gets the championship trophy.
const TIER_ICONS = {
  BIG:   ':rocket:',
  WHALE: ':super-bowl-trophy:',
};
function botIdentity(opp) {
  const winType = classifyWinType(opp);
  const usd = acvUsd(opp);
  const typeLabel = WIN_TYPE_LABELS[winType] || 'Closed';
  const tier = tierWord(usd);
  const username = tier ? `${tier} ${typeLabel} WIN` : `${typeLabel} WIN`;
  const iconEmoji = tier
    ? (TIER_ICONS[tier] || ':super-bowl-trophy:')
    : (WIN_TYPE_ICONS[winType] || ':trophy:');
  return { username, iconEmoji };
}

// ── Field helpers ──────────────────────────────────────────────────────────

// Build a Block Kit field object — returns null when value is null/empty so
// the caller can simply .filter(Boolean) the array to drop empties.
function field(label, value, formatter) {
  if (value === null || value === undefined || value === '') return null;
  const rendered = formatter ? formatter(value) : value;
  if (rendered === null || rendered === undefined || rendered === '') return null;
  return { type: 'mrkdwn', text: `*${label}*\n${rendered}` };
}

function pushSectionWithFields(blocks, headingMrkdwn, fields) {
  const filtered = fields.filter(Boolean);
  if (filtered.length === 0) return false;
  // Heading + fields as TWO separate section blocks — pushing the message
  // above Slack's auto-collapse threshold so the channel feed shows the lead,
  // Dream Team, and Engagement heading with a "Show more" hyperlink for the
  // rest. Mobile clients render the whole thing inline regardless.
  if (headingMrkdwn) {
    blocks.push({ type: 'section', text: { type: 'mrkdwn', text: headingMrkdwn } });
  }
  blocks.push({ type: 'section', fields: filtered.slice(0, 10) }); // Slack max 10 fields
  return true;
}

// ── Main builder ───────────────────────────────────────────────────────────

// Slack user IDs are read straight off each User reference's `Slack_ID__c`
// custom field (Owner, AE__r, Sales_Engineer__r, SDR__r, OpportunityTeamMembers.User
// etc.), so `mentions` is no longer needed — the legacy second arg is accepted
// for backward-compat and merged in only if a caller still passes it.
//
// `peers` is an optional array of recent peer Opps for live cycle comparison
//   { peerCycles: [days...], scope: "New Business / Rental Essentials" }
function buildWinMessage(opp, mentions = {}, peers = null) {
  const winType = classifyWinType(opp);
  const country = opp?.Account?.BillingCountry || '';
  const flag = flagFor(country);
  const usd = acvUsd(opp);
  const tier = tierPrefix(usd);
  const headerLabel = templateLabel(winType);

  const blocks = [];

  // 1. Lead headline — one dynamic summary line that folds in the tier prefix
  //    ("BIG :strong-rocket:", ":lfg: WHALE :whale3:") for $30K+ wins. No
  //    separate banner block above; the tier rides directly on the title.
  const account = opp?.Account?.Name || 'Unknown Account';
  const product = productLabel(opp);
  const lead = leadHeadline({
    headerLabel,
    tierPrefix: tier,
    acv: formatAcv(opp),
    product,
    emoji: product ? productEmoji(product) : '',
    account,
    location: headlineLocation(opp),
    flag,
  });
  blocks.push({
    type: 'section',
    text: { type: 'mrkdwn', text: lead },
  });

  // ── Body sections ────────────────────────────────────────────────────────

  let bodyAdded = false;

  // 5. Dream Team — only if at least one team member resolves
  const teamPushed = pushSectionWithFields(
    blocks,
    ':champion-trophy: *The Dream Team* :air-jordan:',
    dreamTeamFields(opp, mentions),
  );
  bodyAdded = bodyAdded || teamPushed;

  // 6. Engagement — Heading lives in its OWN section block so Slack's
  // auto-collapse "Show more" affordance breaks right after the heading line.
  // The visible-by-default preview is: Lead → Dream Team → Engagement heading,
  // then "Show more" reveals the stats, coach line, and the rest of the body.
  // (Mobile clients show everything inline regardless of length.)
  const engagement = engagementSection(opp);
  if (engagement) {
    if (bodyAdded) blocks.push({ type: 'divider' });
    blocks.push({
      type: 'section',
      text: { type: 'mrkdwn', text: ':like: *Engagement* :gmail:' },
    });
    if (Array.isArray(engagement)) blocks.push(...engagement);
    else blocks.push(engagement);
    bodyAdded = true;
  }

  // 7. Deal Overview — pretty much always non-empty (ACV is the floor).
  if (bodyAdded) blocks.push({ type: 'divider' });
  const dealPushed = pushSectionWithFields(
    blocks,
    ':handshake: *Deal Overview* :handshake:',
    dealOverviewFields(opp, winType),
  );
  bodyAdded = bodyAdded || dealPushed;

  // 7. Migration-only details
  if (winType === WIN_TYPES.MIGRATION) {
    const migFields = migrationFields(opp);
    if (migFields.filter(Boolean).length > 0) {
      if (bodyAdded) blocks.push({ type: 'divider' });
      pushSectionWithFields(
        blocks,
        ':arrows_counterclockwise: *Migration Details* :arrows_counterclockwise:',
        migFields,
      );
      bodyAdded = true;
    }
  }

  // 8. Account Overview — show when any field has data.
  {
    const acctFields = accountFields(opp);
    if (acctFields.filter(Boolean).length > 0) {
      blocks.push({ type: 'divider' });
      pushSectionWithFields(
        blocks,
        ':office: *Account Overview* :office:',
        acctFields,
      );
    }
  }

  // 9. Implementation — skip on Expansion AND when nothing to say
  if (winType !== WIN_TYPES.EXPANSION) {
    const implFields = implementationFields(opp);
    if (implFields.filter(Boolean).length > 0) {
      blocks.push({ type: 'divider' });
      pushSectionWithFields(
        blocks,
        ':hammer_and_wrench: *Implementation Details* :hammer_and_wrench:',
        implFields,
      );
    }
  }

  // 10. Data Insights — Closed date, Sales Cycle, Benchmark, $/Interaction,
  // Daily Burn rendered as a proper section (heading + fields). Benchmark is
  // long prose and rides on the heading text full-width; the four short
  // metrics line up tight in a 2×2 field grid.
  const cycleDays = daysBetween(opp.CreatedDate, opp.CloseDate);
  const productName = productLabel(opp);
  // Compute the peer-relative band first so cycleCharacter can reuse it —
  // keeps the "Sales Cycle" label aligned with the benchmark tagline below
  // (no more "Quick campaign (16d)" paired with "Extended runway, longer
  // than typical 4d").
  const benchBand = cycleBand({
    winType,
    dealType: opp?.Type,
    productFamily: productName,
    country: opp?.Account?.BillingCountry,
    leadSource: opp?.LeadSource,
    days: cycleDays,
  });
  const cycleChar = cycleCharacter(cycleDays, opp.Id, benchBand);
  const livePeer = peers && cycleVsPeers({
    days: cycleDays,
    peerCycles: peers.peerCycles,
    scope: peers.scope,
  });
  const vsBench = livePeer || cycleVsBenchmark({
    winType,
    dealType: opp?.Type,
    productFamily: productName,
    country: opp?.Account?.BillingCountry,
    leadSource: opp?.LeadSource,
    days: cycleDays,
    oppId: opp?.Id,
  });
  const burn = dailyBurn(usd, cycleDays);
  const closedDate = opp.CloseDate ? formatDateLong(opp.CloseDate) : null;
  const counts = activityCounts(opp);
  let perInteractionStr = null;
  if (counts && counts.total > 0 && usd > 0) {
    const perInt = Math.round(usd / counts.total);
    if (perInt > 0) {
      let prefix = '';
      if (perInt >= 5000) prefix = ':gem: ';
      else if (perInt >= 1000) prefix = ':white_check_mark: ';
      else if (perInt < 100) prefix = ':muscle: ';
      perInteractionStr = `${prefix}$${perInt.toLocaleString()}/interaction`;
    }
  }
  // Data Insights — 4 labeled fields in a 2x2 grid for the short metrics,
  // plus the Benchmark line as a full-width context block underneath
  // (smaller grey font, prose-style — fits long-form benchmark text without
  // jamming an odd-height row into the field grid).
  const insightFields = [
    field('Closed', closedDate && closedDate !== '**' ? closedDate : null, d => `:calendar: ${d}`),
    field('Sales Cycle', cycleChar, c => `${cycleEmoji(cycleDays)} ${c} (${cycleDays}d)`),
    field('$/Interaction', perInteractionStr),
    field('Daily Burn', burn),
  ].filter(Boolean);
  if (insightFields.length > 0 || vsBench) {
    blocks.push({ type: 'divider' });
    blocks.push({
      type: 'section',
      text: { type: 'mrkdwn', text: ':data-wow: *Data Insights* :data-eyes:' },
    });
    if (insightFields.length > 0) {
      blocks.push({ type: 'section', fields: insightFields.slice(0, 10) });
    }
    if (vsBench) {
      blocks.push({
        type: 'context',
        elements: [{ type: 'mrkdwn', text: vsBench }],
      });
    }
  }

  // 11. Action row — primary "View Opp" + secondary "Open Account"
  blocks.push({ type: 'divider' });
  blocks.push({
    type: 'actions',
    elements: actionElements(opp),
  });

  // 12. @here ping at the bottom — Slack only fires the channel notification
  // when <!here> appears in a rendered section block, NOT in the `text` fallback.
  if (shouldHerePing(usd)) {
    blocks.push({
      type: 'section',
      text: { type: 'mrkdwn', text: ':loudspeaker: <!here> — come celebrate!' },
    });
  }

  // ── Outer message ────────────────────────────────────────────────────────
  const fallback = leadHeadline({
    headerLabel,
    tierPrefix: tier,
    acv: formatAcv(opp),
    product,
    emoji: product ? productEmoji(product) : '',
    account: opp?.Account?.Name || 'an account',
    location: headlineLocation(opp),
    flag,
    mrkdwn: false,
  });
  const text = shouldHerePing(usd) ? `<!here> ${fallback}` : fallback;
  // color = left-edge sidebar color (consumers wrap blocks in attachments[].color
  // when posting via chat.postMessage — see build-test-workflow.js / build-workflow.js).
  const color = sidebarColor(winType, usd, productLabel(opp));
  return { text, blocks, color };
}

// ── Component builders ─────────────────────────────────────────────────────

function dreamTeamFields(opp, mentions) {
  // Each user reference now carries its own Slack_ID__c straight from the
  // SF query. The `mentions` arg is a legacy email→ID override kept around
  // so old callers (and a few tests) keep working — it wins over Slack_ID__c
  // when both are present, which lets a test inject a specific ID.
  const ownerUser = opp?.Owner;
  // Some opps populate Sales_Engineer__c (a User lookup); others only the
  // SalesEngineer*__c formula text fields. Prefer the lookup so we get an ID.
  const seUser = opp?.Sales_Engineer__r
    || (opp?.SalesEngineerName__c
        ? { Name: opp.SalesEngineerName__c, Email: opp.SalesEngineerEmail__c }
        : null);
  const aeUser = opp?.AE__r;
  const sdrUser = opp?.SDR__r;

  const mentionFor = (user) => {
    if (!user) return null;
    const name = user.Name;
    const email = user.Email;
    const overrideId = mentions && email ? mentions[String(email).toLowerCase()] : undefined;
    const userId = overrideId || user.Slack_ID__c || undefined;
    if (!name && !userId) return null;
    return slackMention(name, userId);
  };

  // AM/AE: prefer the distinct AE when present, otherwise fall back to Owner.
  const aeIsOwner = aeUser?.Name && ownerUser?.Name && aeUser.Name.trim() === ownerUser.Name.trim();
  const amAeValue = !aeIsOwner && aeUser?.Name
    ? mentionFor(aeUser)
    : mentionFor(ownerUser);
  // Label by deal type: New Business deals belong to an AE, while Migration
  // and Expansion (Existing Business) deals belong to an AM. Other types
  // (Credit Card, Consulting) default to AM since the customer relationship
  // sits with the account team.
  const amAeLabel = opp?.Type === 'New Business' ? 'AE' : 'AM';

  return [
    field(amAeLabel, amAeValue),
    field('SE', mentionFor(seUser)),
    field('SDR', mentionFor(sdrUser)),
  ];
}

function dealOverviewFields(opp, winType) {
  const product = productLabel(opp);
  const acv = formatAcv(opp);
  const acvLabel = winType === WIN_TYPES.MIGRATION ? 'ACV Net Increase' : 'ACV';
  const iso = opp.CurrencyIsoCode || 'USD';
  const location = locationLine(opp);

  const moneyOrNull = (v) => (v === null || v === undefined ? null : formatMoney(v, iso));

  // Combined footprint — "1 location · 4 users" — matches the original bot's compact format.
  const footprint = combineFootprint(opp);

  return [
    field(acvLabel, acv),
    field('Product', product, p => `${productEmoji(p)} ${p}`),
    field('Services', opp.Services__c, moneyOrNull),
    field('Hardware', opp.Hardware__c, moneyOrNull),
    field('Footprint', footprint),
    field('Location', location),
    // Lead Source: prefer the deal-level LeadSource (R360 populates this 100%)
    // and fall back to Account.AccountSource (POR's primary source-of-truth, since
    // POR opps leave LeadSource blank ~99% of the time).
    field('Lead Source', opp.LeadSource || opp?.Account?.AccountSource),
    winType !== WIN_TYPES.EXPANSION ? field('SQO Type', opp.SDR_Source__c) : null,
    winType !== WIN_TYPES.EXPANSION ? field('Contract Term', opp.Contract_Length__c) : null,
  ];
}

function combineFootprint(opp) {
  const u = opp.NumUsers__c;
  const l = opp.Number_of_Locations__c;
  const parts = [];
  if (l != null && l > 0) parts.push(`${l} location${l === 1 ? '' : 's'}`);
  if (u != null && u > 0) parts.push(`${u} user${u === 1 ? '' : 's'}`);
  return parts.length ? parts.join(' · ') : null;
}

function migrationFields(opp) {
  const iso = opp.CurrencyIsoCode || 'USD';
  const isR360 = opp?.R360_Record__c === true;
  const newSubSupport = computeNewSubSupport(opp);
  const moneyOrNull = (v) => (v === null || v === undefined ? null : formatMoney(v, iso));

  // R360 doesn't sell support — drop the support pieces from the migration
  // breakdown and use a subscription-only label.
  return [
    field(isR360 ? 'New Subscription' : 'New Subscription + Support', newSubSupport, moneyOrNull),
    field('Previous Subscription', opp.Current_Annual_Subscription__c, moneyOrNull),
    isR360 ? null : field('Previous Support', opp.Current_Annual_Support__c, moneyOrNull),
    field('Pre-Migration Annual Spend', opp.Pre_Migration_Annual_Spend__c, moneyOrNull),
  ];
}

function computeNewSubSupport(opp) {
  const a = opp.Annual_Contract_Value_with_Downpayment__c;
  const b = opp.Current_Annual_Support__c;
  // R360 doesn't sell support — base "new" amount is just the subscription.
  if (opp?.R360_Record__c === true) return a == null ? null : a;
  if (a == null && b == null) return null;
  return (a || 0) + (b || 0);
}

function accountFields(opp) {
  const a = opp.Account || {};
  // Website moved to the action-button row; account-overview now focuses on
  // dimensions you'd skim ("who is this?") rather than links you click.
  // History — count prior wins on the same portfolio as the current opp
  // (POR opps see prior POR wins; R360 opps see prior R360 wins). The
  // workflow's Merge Account Activity step computes this and writes it to
  // Prior_Wins_Scoped__c. Falls back to Account.Num_Closed_Won_Opportunities__c
  // for fixtures and pre-merge contexts.
  const scoped = opp.Prior_Wins_Scoped__c;
  const priorWins = scoped != null ? scoped : a.Num_Closed_Won_Opportunities__c;

  // Account-level Location count. Take the max of the two sources — POR's
  // manually-entered Num_of_Locations__c and the R360-driven Total_Locations__c
  // calc — so we surface whichever side has data. Hidden when both are 0/null.
  const locCount = Math.max(a.Num_of_Locations__c || 0, a.Total_Locations__c || 0);

  // Resolve Industry first, then ask Sub-Industry for a variant that ISN'T
  // the Industry's pick — keeps the section from showing two identical icons
  // when both map to the same variant pool (e.g. Equipment Rental +
  // General Tool & Equipment Rental both pull from the construction-equipment
  // family).
  const indEmoji = industryEmoji(a.Industry, opp.Id);
  const subEmoji = industryEmoji(a.Sub_Industry__c, opp.Id, indEmoji);
  return [
    field('Industry', a.Industry, ind => `${indEmoji} ${ind}`),
    field('Sub-Industry', a.Sub_Industry__c, sub => `${subEmoji} ${sub}`),
    field('Headcount', a.NumberOfEmployees, n => `:bust_in_silhouette: ~${n.toLocaleString()} employees`),
    field('Locations', locCount, n =>
      n > 0 ? `:office: ${n.toLocaleString()} location${n === 1 ? '' : 's'}` : null),
    field('History', priorWins, n =>
      n > 1 ? `:trophy: ${n} prior wins` : null),
  ];
}

function implementationFields(opp) {
  // R360 does not sell support — never show that field on R360 deals even if
  // the Support_Included__c flag happens to be set on the opp record.
  const isR360 = opp?.R360_Record__c === true;
  return [
    field('Contract Start', opp.Contract_Start_Date__c, formatDateLong),
    field('Deployment Type', deploymentModel(opp), v => {
      if (v === 'Cloud') return ':cloud: Cloud';
      if (v === 'On-Prem') return ':desktop_computer: On-Prem';
      return ':cloud::desktop_computer: Cloud + On-Prem';
    }),
    isR360
      ? null
      : opp.Support_Included__c === true
      ? field('Support', 'Included', () => ':white_check_mark: Included')
      : opp.Support_Included__c === false
      ? field('Support', 'Not included', () => ':x: Not included')
      : null,
  ];
}

// Side-by-side action buttons. Slack renders all buttons in one `actions` block
// inline (wraps responsively). Custom POR emojis (:salesforce:, :por:) render
// when `emoji: true`. Buttons drop out cleanly when their target is missing —
// e.g. no Map button for accounts without a billing city.
function actionElements(opp) {
  const elements = [];

  // 1. Primary — open the Opportunity in Lightning
  elements.push({
    type: 'button',
    text: { type: 'plain_text', text: ':salesforce: Opportunity', emoji: true },
    url: opportunityUrl(opp.Id),
    style: 'primary',
  });

  // 2. Open Account — secondary SF nav, default grey (so Opportunity stays
  //    the only green primary CTA)
  const accountId = opp?.Account?.Id || opp?.AccountId;
  const acctLink = accountUrl(accountId);
  if (acctLink) {
    elements.push({
      type: 'button',
      text: { type: 'plain_text', text: ':salesforce: Account', emoji: true },
      url: acctLink,
    });
  }

  // 3. Google Maps — danger (red button) + :google: emoji (Google's brand G in
  //    yellow/red/green/blue — instantly recognizable, far more on-brand than
  //    a generic :round_pushpin:). Confirmed present in POR Slack workspace.
  const map = mapUrl(opp);
  if (map) {
    elements.push({
      type: 'button',
      text: { type: 'plain_text', text: ':google: Map', emoji: true },
      url: map,
      style: 'danger',
    });
  }

  // 4. Website — neutral grey + globe emoji. Distinct from the other three
  //    buttons since it's a third-party customer site, not a POR system.
  //    Falls back to a Google search on the account name when SF has no
  //    Website on file, so the button is always useful for the customer.
  const site = accountWebsiteOrSearchUrl(opp?.Account);
  if (site) {
    elements.push({
      type: 'button',
      text: { type: 'plain_text', text: ':globe_with_meridians: Website', emoji: true },
      url: site,
    });
  }

  return elements;
}


// n8n Code node — mode runOnceForEachItem — runs ONCE per Opportunity.
// Input: $input.item.json is one Opportunity record from the Salesforce node.
// Output: a single item with Slack-ready blocks + metadata for downstream nodes.
// Slack user IDs are read live from each User reference's Slack_ID__c field
// (see soql/closed-won.soql); no email→ID cache needed.

const opp = $input.item.json;

// Live peer comparison disabled — see PEER_SOQL_EXPR comment above. Falls
// back to the static cycleVsBenchmark inside lib/slack-blocks.js.
const peers = null;

const message = buildWinMessage(opp, {}, peers);

// Use the corrected USD-equivalent of the actual annual ACV (acvUsd helper
// from format-helpers.js — picks ACV_with_Downpayment_Corporate_Currency__c
// over the inflated ACV_in_USD__c formula).
const usdAcv = acvUsd(opp) || 0;
const ownerName          = (opp.Owner && opp.Owner.Name) || '';
const ownerEmail         = (opp.Owner && opp.Owner.Email) || '';
const ownerTitle         = (opp.Owner && opp.Owner.Title) || '';
const ownerDepartment    = (opp.Owner && opp.Owner.Department) || '';
const ownerProfileName   = (opp.Owner && opp.Owner.Profile && opp.Owner.Profile.Name) || '';
const ownerRoleName      = (opp.Owner && opp.Owner.UserRole && opp.Owner.UserRole.Name) || '';
const ownerManagerSlackId = (opp.Owner && opp.Owner.Manager && opp.Owner.Manager.Slack_ID__c) || null;
const ownerManagerEmail   = (opp.Owner && opp.Owner.Manager && opp.Owner.Manager.Email)        || null;
const ownerManagerName    = (opp.Owner && opp.Owner.Manager && opp.Owner.Manager.Name)         || null;
// Wins channel: $1K USD floor, so the channel doesn't drown in micro-renewals.
// Alert channel: any ACV > 0 (no $1K gate) — even sub-$1K deals on a flagged
// manager's team count as a CPQ policy violation worth flagging.
// Mutually exclusive: a deal flagged as a CPQ Policy Violation goes ONLY to
// the alert channel, never to #rev-wins (the wins-branch gate enforces this
// by also checking !shouldFireAlert).
const meetsThreshold  = usdAcv >= 1000;
// Two independent triggers for the alert channel:
//   (a) Owner reports up to one of the flagged managers (Kirk/Erick/Colin)
//   (b) Owner is an accounting user — checked across Name, Title, Department,
//       Profile.Name, and UserRole.Name because production accounting users
//       (e.g. Brianna Steckman, exec 2026-05-15) have plain personal names
//       and are only identifiable as accounting via Title="Accounting Manager",
//       Profile="Accounting", or UserRole="Accounting User". Name alone misses
//       them; the alert fired on her two wins after this widening.
// Allowlist short-circuits false positives where a real Account Manager's
// Title was typed as "Accounting Manager" (Julia, 2026-05-19).
const accountingUserOwnsDeal = !["julia.marcinkiewicz@pointofrental.com"].includes(String(ownerEmail).toLowerCase())
  && /accounting/i.test(
    ownerName + ' ' + ownerTitle + ' ' + ownerDepartment + ' ' + ownerProfileName + ' ' + ownerRoleName
  );
const shouldFireAlert = usdAcv > 0 && (
  ["U02HR1T6PBK","U01S2GKUVN1","U06LAC2PZ8C"].includes(ownerManagerSlackId) || accountingUserOwnsDeal
);
// Pre-compose the alert text in JS so the Slack node doesn't have to ternary
// on (a) whether to ping a manager Slack ID and (b) which reason to print.
// The "accounting user" trigger may fire on owners with no manager mapped, so
// the @ping is conditional. When both triggers fire, manager ping wins.
const alertPing = ownerManagerSlackId ? ('<@' + ownerManagerSlackId + '> ') : '';
const alertReason = ["U02HR1T6PBK","U01S2GKUVN1","U06LAC2PZ8C"].includes(ownerManagerSlackId)
  ? 'owner reports to you'
  : 'accounting user owns deal';
const alertAccount = (opp.Account && opp.Account.Name) || 'Unknown Account';
const alertText = alertPing + '*CPQ Policy Violation* — ' + alertAccount
  + ' (ACV $' + Math.round(usdAcv) + ', ' + alertReason + ')';

// Deployment model + backfill plan. Computed once here so downstream nodes
// (Slack render + SF backfill) read consistent values from this Code node.
const detectedDeployment = deploymentModel(opp);
const backfillDeployment = shouldBackfillDeployment(opp);
const primaryQuoteId     = opp.SBQQ__PrimaryQuote__c || null;

// Per-deal bot identity — picks username + icon from win type & tier so the
// channel can scan message type from the username without reading the blocks.
const identity = botIdentity(opp);

// Wrap the blocks in attachments[] so Slack triggers its auto-collapse
// "Show more" affordance — the n8n native slackNode posts top-level blocks
// which Slack does NOT auto-collapse. attachments[].blocks (with the colored
// sidebar) DO collapse.
const slackBody = {
  channel: "C06T48V2A0J",
  username: identity.username,
  icon_emoji: identity.iconEmoji,
  attachments: [{
    color: message.color,
    blocks: message.blocks,
    fallback: message.text,
  }],
};

return {
  json: {
    opportunityId: opp.Id,
    accountName: opp.Account && opp.Account.Name,
    winType: classifyWinType(opp),
    acvNative: opp.Annual_Contract_Value_with_Downpayment__c,
    acvUsd: usdAcv,
    currencyIso: opp.CurrencyIsoCode,
    fallbackText: message.text,
    blocks: message.blocks,
    slackBody,
    slackChannel: "C06T48V2A0J",
    closeDate: opp.CloseDate,
    reactionEmoji: reactionEmoji(usdAcv),
    meetsThreshold,
    shouldFireAlert,
    accountingUserOwnsDeal,
    alertText,
    detectedDeployment,
    backfillDeployment,
    primaryQuoteId,
    ownerName,
    ownerManagerSlackId,
    ownerManagerEmail,
    ownerManagerName,
    botUsername: identity.username,
    botIconEmoji: identity.iconEmoji,
  }
};

